input.content:
/* ============ Crônicas de Aetheria — UI ============ */
* { margin:0; padding:0; box-sizing:border-box; }
:root {
  --gold:#e8c26a; --gold-dim:#a88842;
  --hp:#c0392b; --mp:#2980b9; --sp:#27ae60;
  --panel:rgba(16,12,8,.88); --panel-border:#5a4326;
  --text:#e8dcc0; --text-dim:#b7a888;
}
html,body { width:100%; height:100%; overflow:hidden; background:#060505; }
body { font-family: Georgia, 'Times New Roman', serif; color:var(--text); -webkit-user-select:none; user-select:none; }
button { font-family:inherit; cursor:pointer; }
.hidden { display:none !important; }
#game-canvas { position:fixed; inset:0; width:100%; height:100%; display:block; }

/* ---------- Loading / Error ---------- */
#loading-screen, #error-screen {
  position:fixed; inset:0; z-index:2000; display:flex; align-items:center; justify-content:center;
  background:radial-gradient(ellipse at 50% 40%, #1a1410 0%, #060505 75%);
}
.loading-inner, .error-box { text-align:center; }
.loading-sigil { font-size:64px; color:var(--gold); animation:sigilPulse 2s infinite; text-shadow:0 0 24px #e8c26a88; }
@keyframes sigilPulse { 0%,100%{opacity:.55; transform:scale(1)} 50%{opacity:1; transform:scale(1.12)} }
.loading-inner h1, .error-box h1 { letter-spacing:.35em; font-size:26px; color:var(--gold); margin:14px 0 22px; font-weight:normal; }
.loading-bar { width:320px; height:10px; margin:0 auto; border:1px solid var(--panel-border); border-radius:6px; overflow:hidden; background:#0d0a08; }
#loading-fill { height:100%; width:0%; background:linear-gradient(90deg,#7a5a24,var(--gold)); transition:width .3s; }
#loading-text { margin-top:14px; color:var(--text-dim); font-size:14px; font-style:italic; }
.error-box { max-width:520px; padding:40px; background:var(--panel); border:1px solid var(--panel-border); border-radius:12px; }
.error-icon { font-size:56px; margin-bottom:10px; }
.error-box p { color:var(--text-dim); margin:10px 0; font-size:15px; }
.error-detail { font-family:monospace; font-size:12px; color:#c98; max-height:120px; overflow:auto; word-break:break-all; }
.error-box button { margin-top:18px; padding:10px 26px; background:linear-gradient(#3a2c18,#241a0e); color:var(--gold); border:1px solid var(--panel-border); border-radius:8px; font-size:16px; }

/* ---------- Menu ---------- */
#menu-screen {
  position:fixed; inset:0; z-index:1500; display:flex; align-items:center; justify-content:center;
  background:radial-gradient(ellipse at 50% 30%, #241a12 0%, #0a0705 70%);
}
.menu-inner { text-align:center; }
.game-title { font-size:44px; letter-spacing:.3em; color:var(--gold); font-weight:normal; text-shadow:0 0 30px #e8c26a55, 0 2px 6px #000; }
.game-subtitle { color:var(--text-dim); font-style:italic; margin:8px 0 38px; letter-spacing:.15em; }
#menu-buttons { display:flex; flex-direction:column; gap:12px; width:280px; margin:0 auto; }
#menu-buttons button {
  padding:12px; font-size:17px; background:linear-gradient(#2c2216,#1a130b); color:var(--text);
  border:1px solid var(--panel-border); border-radius:8px; letter-spacing:.08em; transition:all .15s;
}
#menu-buttons button:hover:not(.disabled) { background:linear-gradient(#4a3820,#2c2212); color:var(--gold); transform:scale(1.03); }
#menu-buttons button.disabled { opacity:.35; cursor:default; }
.menu-footer { margin-top:34px; color:#74624a; font-size:12px; }
#menu-panel {
  position:absolute; top:50%; left:50%; transform:translate(-50%,-50%);
  width:min(640px, 92vw); max-height:80vh; overflow:auto; padding:28px;
  background:var(--panel); border:1px solid var(--panel-border); border-radius:12px; text-align:left;
}
#menu-panel h2 { color:var(--gold); letter-spacing:.2em; font-weight:normal; margin-bottom:18px; text-align:center; }
#menu-panel .row { display:flex; align-items:center; justify-content:space-between; margin:12px 0; gap:16px; }
#menu-panel .row label { color:var(--text-dim); }
#menu-panel .row input[type=range] { width:200px; accent-color:var(--gold); }
#menu-panel .row select { background:#241a0e; color:var(--text); border:1px solid var(--panel-border); padding:4px 8px; border-radius:4px; }
#menu-panel .close-btn { display:block; margin:20px auto 0; padding:8px 30px; background:#2c2216; color:var(--gold); border:1px solid var(--panel-border); border-radius:6px; }
#menu-panel .ctl { color:var(--text-dim); margin:7px 0; font-size:15px; }
#menu-panel .ctl b { color:var(--text); display:inline-block; min-width:170px; color:var(--gold); }

/* ---------- HUD ---------- */
#hud { position:fixed; inset:0; z-index:500; pointer-events:none; }
#hud-topleft { position:absolute; top:14px; left:14px; }
#player-plate { display:flex; flex-direction:column; gap:6px; }
.bars { display:flex; flex-direction:column; gap:4px; width:250px; }
.bar-row { display:flex; align-items:center; gap:6px; }
.bar-row.xp { margin-top:2px; }
.bar-label { font-size:10px; width:20px; color:var(--text-dim); letter-spacing:.1em; }
.bar { position:relative; height:15px; background:rgba(0,0,0,.55); border:1px solid #00000088; border-radius:8px; overflow:hidden; flex:1; }
.bar div { height:100%; width:100%; transition:width .18s; }
.bar.hp div { background:linear-gradient(#e74c3c,#922b21); }
.bar.mp div { background:linear-gradient(#3498db,#21618c); }
.bar.sp div { background:linear-gradient(#2ecc71,#1e8449); }
.bar.xp { height:7px; border-radius:4px; }
.bar.xp div { background:linear-gradient(90deg,#8e6b2f,var(--gold)); }
.bar span { position:absolute; inset:0; font-size:10px; text-align:center; line-height:15px; color:#fff; text-shadow:0 1px 2px #000; }
#lvl-text { font-size:11px; color:var(--gold); min-width:44px; }
#element-badge { display:inline-flex; align-items:center; gap:6px; margin-top:2px; padding:3px 10px; background:var(--panel); border:1px solid var(--panel-border); border-radius:12px; font-size:12px; }
#quest-tracker { margin-top:10px; padding:8px 12px; background:var(--panel); border-left:3px solid var(--gold); border-radius:4px; max-width:300px; }
#quest-title { color:var(--gold); font-size:13px; letter-spacing:.05em; }
#quest-objective { font-size:12px; color:var(--text-dim); margin-top:3px; }
#quest-dist { font-size:11px; color:#8fa8c9; margin-top:2px; }
#hud-topright { position:absolute; top:14px; right:14px; text-align:right; display:flex; flex-direction:column; align-items:flex-end; gap:6px; }
#gold-display, #clock-display { padding:4px 12px; background:var(--panel); border:1px solid var(--panel-border); border-radius:12px; font-size:13px; }
#minimap { border:2px solid var(--panel-border); border-radius:50%; background:#0a0806aa; }
#region-name { font-size:14px; color:var(--gold); text-shadow:0 1px 4px #000; letter-spacing:.12em; font-style:italic; }
#boss-bar { position:absolute; top:64px; left:50%; transform:translateX(-50%); width:min(560px,80vw); text-align:center; }
#boss-name { color:#e6b422; font-size:17px; letter-spacing:.25em; text-shadow:0 2px 6px #000; margin-bottom:4px; }
.bar.boss { height:14px; border:1px solid #7a4a1a; }
.bar.boss div { background:linear-gradient(#ff6a3d,#a02010); }
#crosshair { position:absolute; top:50%; left:50%; transform:translate(-50%,-50%); color:#fff8; font-size:20px; text-shadow:0 0 4px #000; }
