        case 'fire': this.noise(0, { dur: 0.6, freq: 300, q: 0.4, vol: 0.3, slide: 0.5 }); this.noise(0.05, { dur: 0.5, freq: 1200, q: 1, vol: 0.15, slide: 0.3 }); break;
