// Salvamento — LocalStorage com fallback seguro
import { settings, saveSettings } from '../core/config.js';
import { safeGet } from '../core/utils.js';

const SAVE_KEY = 'aetheria_save_v1';

const DEFAULT_SAVE = {
  version: 1,
  // personagem
  level: 1, xp: 0, gold: 0,
  hp: 100, mp: 50,
  attributes: { forca: 5, defesa: 5, velocidade: 5, mana: 5, poder: 5, resistencia: 5, critico: 5 },
  attrPoints: 0,
  element: null,
  spells: {},           // id -> { level, uses }
  equipment: { weapon: null, armor: null, helmet: null, gloves: null, boots: null, cape: null, accessory: null },
  inventory: [],        // { id, qty }
  // mundo / história
  chapter: 1,
  storyFlags: {},
  quests: {},           // id -> { state:'active'|'done', progress, step }
  discovered: [],
  pos: { x: 0, z: 0 },
  timeOfDay: 9,
  playtime: 0,
  grimoireLevel: 1,
};

export function loadSave() {
  try {
    const raw = localStorage.getItem(SAVE_KEY);
    if (!raw) return null;
    const data = JSON.parse(raw);
    if (!data || typeof data !== 'object') return null;
    // merge com padrões para tolerar saves antigos
    const merged = { ...DEFAULT_SAVE, ...data };
    merged.attributes = { ...DEFAULT_SAVE.attributes, ...(data.attributes || {}) };
    merged.equipment = { ...DEFAULT_SAVE.equipment, ...(data.equipment || {}) };
    return merged;
  } catch (e) { console.warn('Save corrompido, ignorado.', e); return null; }
}

export function hasSave() { try { return !!localStorage.getItem(SAVE_KEY); } catch { return false; } }

export function writeSave(state) {
  try {
    const data = {
      ...DEFAULT_SAVE,
      version: 1,
      level: state.level, xp: state.xp, gold: state.gold,
      hp: state.hp, mp: state.mp,
      attributes: { ...state.attributes }, attrPoints: state.attrPoints || 0,
      element: state.element, spells: state.spells, equipment: { ...state.equipment },
      inventory: state.inventory.map(i => ({ ...i })),
      chapter: state.chapter, storyFlags: state.storyFlags,
      quests: state.quests, discovered: [...state.discovered],
      pos: state.savePos, timeOfDay: state.timeOfDay, playtime: Math.floor(state.playtime),
      grimoireLevel: state.grimoireLevel,
    };
    localStorage.setItem(SAVE_KEY, JSON.stringify(data));
    saveSettings();
    return true;
  } catch (e) { console.warn('Falha ao salvar:', e); return false; }
}

export function deleteSave() { try { localStorage.removeItem(SAVE_KEY); } catch (e) {} }

// Sistema de partículas e efeitos — pool única, baixa alocação
import * as THREE from 'three';
import { G } from '../core/state.js';
import { settings } from '../core/config.js';
import { rand } from '../core/utils.js';

const MAX_PARTICLES = 900;

class Particles {
  constructor() {
    this.geo = new THREE.BufferGeometry();
    this.pos = new Float32Array(MAX_PARTICLES * 3);
    this.col = new Float32Array(MAX_PARTICLES * 3);
    this.size = new Float32Array(MAX_PARTICLES);
    for (let i = 0; i < MAX_PARTICLES; i++) { this.size[i] = 0; this.pos[i * 3 + 1] = -9999; }
    this.geo.setAttribute('position', new THREE.BufferAttribute(this.pos, 3));
    this.geo.setAttribute('color', new THREE.BufferAttribute(this.col, 3));
    this.geo.setAttribute('size', new THREE.BufferAttribute(this.size, 1));
    this.mat = new THREE.ShaderMaterial({
      transparent: true, depthWrite: false, blending: THREE.AdditiveBlending,
      vertexShader: `
        attribute float size; varying vec3 vColor;
        void main(){ vColor = color; vec4 mv = modelViewMatrix * vec4(position,1.0);
          gl_PointSize = size * (220.0 / max(1.0, -mv.z)); gl_Position = projectionMatrix * mv; }`,
      fragmentShader: `
        varying vec3 vColor;
        void main(){ float d = length(gl_PointCoord - vec2(0.5)); if(d > 0.5) discard;
          float a = smoothstep(0.5, 0.05, d); gl_FragColor = vec4(vColor, a); }`,
      vertexColors: true,
    });
    this.points = new THREE.Points(this.geo, this.mat);
    this.points.frustumCulled = false;
    this.points.renderOrder = 5;
    this.items = [];   // {i, x,y,z, vx,vy,vz, life, maxLife, size, r,g,b, drag, grav, fadePow}
    this.free = [];
    for (let i = 0; i < MAX_PARTICLES; i++) this.free.push(i);
    this.scale = 1;
  }
  emit(o) {
    if (this.free.length === 0) return;
    const i = this.free.pop();
    const maxLife = (o.life || 0.8);
    this.items.push({
      i, x: o.x, y: o.y, z: o.z,
      vx: o.vx || 0, vy: o.vy || 0, vz: o.vz || 0,
      life: maxLife, maxLife,
      size: o.size || 0.4,
      r: o.r ?? 1, g: o.g ?? 1, b: o.b ?? 1,
      drag: o.drag ?? 0.9, grav: o.grav ?? 0,
      spread: o.spread || 0,
    });
  }
  burst(x, y, z, n, opts = {}) {
    const count = Math.max(1, Math.round(n * this.scale * settings.particles));
    for (let k = 0; k < count; k++) {
      const s = opts.spread ?? 1;
      this.emit({
        x, y, z,
        vx: rand(-s, s), vy: rand(opts.up ?? 0.5, (opts.up ?? 0.5) + s), vz: rand(-s, s),
        life: opts.life || rand(0.4, 0.9),
        size: opts.size || rand(0.2, 0.5),
        r: opts.r ?? 1, g: opts.g ?? 1, b: opts.b ?? 1,
        drag: opts.drag ?? 0.92, grav: opts.grav ?? 0, spread: 0,
      });
    }
  }
  update(dt) {
    for (let k = this.items.length - 1; k >= 0; k--) {
      const p = this.items[k];
      p.life -= dt;
      if (p.life <= 0) {
        this.pos[p.i * 3 + 1] = -9999; this.size[p.i] = 0;
        this.items[k] = this.items[this.items.length - 1]; this.items.pop();
        this.free.push(p.i);
        continue;
      }
      const dr = Math.pow(p.drag, dt * 60);
      p.vx *= dr; p.vz *= dr; p.vy = p.vy * dr - p.grav * dt;
      p.x += p.vx * dt; p.y += p.vy * dt; p.z += p.vz * dt;
      const f = p.life / p.maxLife;
      const idx = p.i * 3;
      this.pos[idx] = p.x; this.pos[idx + 1] = p.y; this.pos[idx + 2] = p.z;
      this.col[idx] = p.r; this.col[idx + 1] = p.g; this.col[idx + 2] = p.b;
      this.size[p.i] = p.size * (0.35 + 0.65 * f);
    }
    this.geo.attributes.position.needsUpdate = true;
    this.geo.attributes.color.needsUpdate = true;
    this.geo.attributes.size.needsUpdate = true;
  }
}

// efeitos de cores por elemento
export const ELEMENT_COLORS = {
  fogo:  { r: 1.0, g: 0.35, b: 0.08, hex: 0xff5515 },
  agua:  { r: 0.25, g: 0.6, b: 1.0, hex: 0x3d8bff },
  raio:  { r: 1.0, g: 0.9, b: 0.2, hex: ffe633 },
  terra: { r: 0.7, g: 0.45, b: 0.2, hex: 0xb37433 },
  vento: { r: 0.7, g: 1.0, b: 0.75, hex: 0xb3ffbf },
  gelo:  { r: 0.55, g: 0.85, b: 1.0, hex: 0x8cd9ff },
};

class Effects {
  constructor() {
    this.particles = new Particles();
    this.tempMeshes = [];   // { mesh, life, maxLife, shrink, fade }
    this.pool = [];         // meshes genéricos reutilizáveis (esferas)
  }
  init(scene) {
    scene.add(this.particles.points);
    this.scene = scene;
    this.scale = settings.particles;
  }
  // esfera de efeito temporária (impactos, AoE)
  flashSphere(x, y, z, radius, color, life = 0.4, opacity = 0.7) {
    let mesh = this.pool.pop();
    if (!mesh) {
      const geo = new THREE.SphereGeometry(1, 12, 10);
      const mat = new THREE.MeshBasicMaterial({ transparent: true, opacity, depthWrite: false, blending: THREE.AdditiveBlending });
      mesh = new THREE.Mesh(geo, mat);
      mesh.renderOrder = 6;
    }
    mesh.material.color.setHex(color);
    mesh.material.opacity = opacity;
    mesh.position.set(x, y, z);
    mesh.scale.setScalar(radius);
    mesh.visible = true;
    this.scene.add(mesh);
    this.tempMeshes.push({ mesh, life, maxLife: life, radius, opacity });
    return mesh;
  }
  // projétil mágico visual (devolve mesh controlado pelo chamador)
  makeProjectileMesh(color, radius = 0.25) {
    const geo = new THREE.SphereGeometry(radius, 10, 8);
    const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.95 });
    const mesh = new THREE.Mesh(geo, mat);
    const glow = new THREE.Mesh(new THREE.SphereGeometry(radius * 1.8, 10, 8),
      new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.3, blending: THREE.AdditiveBlending, depthWrite: false }));
    mesh.add(glow);
    return mesh;
  }
  hit(x, y, z, colorHex, n = 14, size = 0.4) {
    const c = new THREE.Color(colorHex);
    this.particles.burst(x, y, z, n, { r: c.r, g: c.g, b: c.b, spread: 3, up: 1, life: 0.55, size, grav: 4, drag: 0.9 });
    this.flashSphere(x, y, z, size * 2.4, colorHex, 0.25, 0.5);
  }
  explosion(x, y, z, colorHex, n = 40, radius = 3) {
    const c = new THREE.Color(colorHex);
    this.particles.burst(x, y, z, n, { r: c.r, g: c.g, b: c.b, spread: 6, up: 2, life: 0.9, size: 0.6, grav: 3, drag: 0.88 });
    this.flashSphere(x, y, z, radius, colorHex, 0.5, 0.75);
    this.flashSphere(x, y, z, radius * 0.55, 0xffffff, 0.22, 0.9);
  }
  update(dt) {
    this.particles.update(dt);
    for (let i = this.tempMeshes.length - 1; i >= 0; i--) {
      const t = this.tempMeshes[i];
      t.life -= dt;
      if (t.life <= 0) {
        this.scene.remove(t.mesh);
        this.pool.push(t.mesh);
        this.tempMeshes.splice(i, 1);
        continue;
      }
      const f = t.life / t.maxLife;
      t.mesh.scale.setScalar(t.radius * (0.35 + 0.75 * (1 - f) + 0.25 * f));
      t.mesh.material.opacity = t.opacity * f;
    }
  }
}

export const effects = new Effects();

// Terreno — heightfield procedural determinístico + água
import * as THREE from 'three';

export const WORLD_SIZE = 1000;
export const WATER_LEVEL = 0.55;

// regiões-chave do mundo (coordenadas fixas)
export const WORLD = {
  village:   { x: 0,     z: 0    },
  city:      { x: 0,     z: -260 },
  forest:    { x: 230,   z: 60   },
  lake:      { x: -200,  z: -60  },
  mountains: { x: 330,   z: -260 },
  volcano:   { x: 400,   z: 260  },
  frozen:    { x: -380,  z: -340 },
  swamp:     { x: -230,  z: 260  },
  goblin:    { x: 300,   z: 320  },
  ruins:     { x: -360,  z: 160  },
  cave:      { x: 150,   z: 200  },
};

const MOUNTAINS = [
  { x: 330, z: -260, r: 150, h: 55 },   // montanhas
  { x: 420, z: -80, r: 90, h: 30 },
  { x: 160, z: -420, r: 100, h: 40 },
  { x: -140, z: -450, r: 120, h: 45 },
  { x: 460, z: 100, r: 110, h: 50 },
];

// ribeira sinuosa indo do lago para o pântano (ao sul)
function riverX(z) { return -170 + 60 * Math.sin(z * 0.012) + 30 * Math.sin(z * 0.033); }

export function terrainHeight(x, z) {
  // colinas suaves
  let y = 2.2
    + 1.6 * Math.sin(x * 0.018) * Math.cos(z * 0.021)
    + 0.9 * Math.sin(x * 0.045 + 1.3) * Math.cos(z * 0.041 + 0.7)
    + 0.4 * Math.sin(x * 0.09) * Math.cos(z * 0.087 + 2.1);

  // montanhas
  for (const m of MOUNTAINS) {
    const d = Math.hypot(x - m.x, z - m.z);
    if (d < m.r) {
      const t = 1 - d / m.r;
      y += m.h * t * t * (3 - 2 * t) * 0.9;
    }
  }

  // vulcão: cone com cratera
  {
    const d = Math.hypot(x - WORLD.volcano.x, z - WORLD.volcano.z);
    const R = 110;
    if (d < R) {
      const t = 1 - d / R;
      y += 46 * Math.pow(t, 1.6);
      if (d < 22) y -= (1 - d / 22) * 20; // cratera
    }
  }

  // região congelada: platô elevado
  {
    const d = Math.hypot(x - WORLD.frozen.x, z - WORLD.frozen.z);
    if (d < 170) { const t = 1 - d / 170; y += 7 * t * t + 3 * t; }
  }

  // pântano: abaixa
  {
    const d = Math.hypot(x - WORLD.swamp.x, z - WORLD.swamp.z);
    if (d < 130) { const t = 1 - d / 130; y -= 3.2 * t * (2 - t); }
  }

  // rio esculpido
  {
    const d = Math.abs(x - riverX(z));
    if (d < 14) {
      const t = 1 - d / 14;
      y = THREE.MathUtils.lerp(y, -1.6, t * t * (3 - 2 * t));
    }
  }

  // lago: bacia
  {
    const d = Math.hypot(x - WORLD.lake.x, z - WORLD.lake.z);
    const R = 78;
    if (d < R) { const t = 1 - d / R; y = THREE.MathUtils.lerp(y, -3.2, Math.min(1, t * 1.7) * t); }
  }

  // vila: área plana
  {
    const d = Math.hypot(x - WORLD.village.x, z - WORLD.village.z);
    if (d < 80) { const t = Math.min(1, (80 - d) / 30); y = THREE.MathUtils.lerp(y, 2.0, t); }
  }

  // cidade + castelo: planalto plano
  {
    const d = Math.hypot(x - WORLD.city.x, z - WORLD.city.z);
    if (d < 110) { const t = Math.min(1, (110 - d) / 34); y = THREE.MathUtils.lerp(y, 3.0, t); }
  }

  // borda do mundo: muralha de montanhas
  {
    const edge = Math.max(Math.abs(x), Math.abs(z));
    if (edge > 400) y += Math.pow((edge - 400) / 100, 2) * 90;
  }

  return y;
}

// normal aproximada via diferenças finitas
export function terrainNormal(x, z, out) {
  const e = 1.2;
  const hL = terrainHeight(x - e, z), hR = terrainHeight(x + e, z);
  const hD = terrainHeight(x, z - e), hU = terrainHeight(x, z + e);
  out.set(hL - hR, 2 * e, hD - hU).normalize();
  return out;
}

// cor do terreno conforme altura/região
function terrainColor(x, z, y, target) {
  const inVolcano = Math.hypot(x - WORLD.volcano.x, z - WORLD.volcano.z) < 130;
  const frozenD = Math.hypot(x - WORLD.frozen.x, z - WORLD.frozen.z);
  const swampD = Math.hypot(x - WORLD.swamp.x, z - WORLD.swamp.z);
  const goblinD = Math.hypot(x - WORLD.goblin.x, z - WORLD.goblin.z);

  if (y < WATER_LEVEL + 0.9) target.set(0.78, 0.70, 0.48);            // areia
  else if (y > 26) target.set(0.82, 0.85, 0.9);                       // neve alta
  else if (frozenD < 150 || y > 15) target.set(0.85, 0.88, 0.92);     // neve
  else if (inVolcano || y > 34) target.set(0.28, 0.16, 0.12);         // rocha vulcânica
  else if (y > 22) target.set(0.45, 0.42, 0.4);                       // rocha
  else if (swampD < 120) target.set(0.32, 0.38, 0.22);                // pântano
  else if (goblinD < 120) target.set(0.42, 0.42, 0.25);               // terra goblin
  else target.set(0.34, 0.55, 0.25);                                  // grama

  // variação sutil
  const n = 0.92 + 0.08 * Math.sin(x * 0.35) * Math.cos(z * 0.3);
  target.multiplyScalar(n);
}

export function buildTerrain(scene) {
  const SEG = 180;
  const geo = new THREE.PlaneGeometry(WORLD_SIZE, WORLD_SIZE, SEG, SEG);
  geo.rotateX(-Math.PI / 2);
  const pos = geo.attributes.position;
  const colors = new Float32Array(pos.count * 3);
  const c = new THREE.Color();
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i), z = pos.getZ(i);
    const y = terrainHeight(x, z);
    pos.setY(i, y);
    terrainColor(x, z, y, c);
    colors[i * 3] = c.r; colors[i * 3 + 1] = c.g; colors[i * 3 + 2] = c.b;
  }
  geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  geo.computeVertexNormals();
  const mat = new THREE.MeshLambertMaterial({ vertexColors: true });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.receiveShadow = true;
  mesh.name = 'terrain';
  scene.add(mesh);
  return mesh;
}

export function buildWater(scene) {
  const geo = new THREE.PlaneGeometry(WORLD_SIZE, WORLD_SIZE, 1, 1);
  geo.rotateX(-Math.PI / 2);
  const mat = new THREE.MeshLambertMaterial({
    color: 0x2a6a9e, transparent: true, opacity: 0.72,
    emissive: 0x0a2033, emissiveIntensity: 0.4,
  });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.position.y = WATER_LEVEL;
  mesh.renderOrder = 1;
  scene.add(mesh);
  return mesh;
}

// ribbons de estrada acompanhando o relevo
export function buildRoad(scene, points, width = 4.5) {
  const verts = [], idx = [];
  const half = width / 2;
  for (let i = 0; i < points.length; i++) {
    const p = points[i];
    const next = points[Math.min(i + 1, points.length - 1)];
    const prev = points[Math.max(i - 1, 0)];
    const dx = next.x - prev.x, dz = next.z - prev.z;
    const len = Math.hypot(dx, dz) || 1;
    const nx = -dz / len * half, nz = dx / len * half;
    const y0 = terrainHeight(p.x + nx, p.z + nz) + 0.06;
    const y1 = terrainHeight(p.x - nx, p.z - nz) + 0.06;
    verts.push(p.x + nx, y0, p.z + nz, p.x - nx, y1, p.z - nz);
    if (i < points.length - 1) {
      const a = i * 2;
      idx.push(a, a + 1, a + 2, a + 1, a + 3, a + 2);
    }
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(verts), 3));
  geo.setIndex(idx);
  geo.computeVertexNormals();
  const mat = new THREE.MeshLambertMaterial({ color: 0x8a7150 });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.receiveShadow = true;
  scene.add(mesh);
  return mesh;
}

// Céu — ciclo dia/noite, sol, lua, estrelas, nuvens, clima
import * as THREE from 'three';
import { G } from '../core/state.js';
import { settings } from '../core/config.js';
import { clamp, lerp, rand } from '../core/utils.js';

const DAY_SECONDS = 480; // 8 min = 24h de jogo (1 min de jogo = 20s)

const SKY_PRESETS = { // [topo, horizonte, luzSol, corLuz, ambiente, neblina]  por fase
  dawn:  { top: 0x2a3a6e, hor: 0xe8946a, sun: 0xffb070, amb: 0x58506a, fog: 0xd09070, sunI: 0.55 },
  day:   { top: 0x2e6fd4, hor: 0xaee0f7, sun: 0xfff2d8, amb: 0x6e7d8c, fog: 0xa8c4d8, sunI: 1.35 },
  dusk:  { top: 0x352a5e, hor: 0xf08050, sun: 0xff7a40, amb: 0x50425e, fog: 0xc06850, sunI: 0.5 },
  night: { top: 0x060816, hor: 0x101828, sun: 0x7080b8, amb: 0x1c2030, fog: 0x0c1220, sunI: 0.14 },
};

export class Sky {
  constructor(scene) {
    this.scene = scene;
    this.time = G.timeOfDay; // 0-24
    this.dayNum = 0;

    // cúpula do céu
    this.skyGeo = new THREE.SphereGeometry(700, 24, 16);
    this.skyMat = new THREE.ShaderMaterial({
      side: THREE.BackSide, depthWrite: false,
      uniforms: { topColor: { value: new THREE.Color(0x2e6fd4) }, horColor: { value: new THREE.Color(0xaee0f7) } },
      vertexShader: `varying vec3 vP; void main(){ vP = position; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
      fragmentShader: `uniform vec3 topColor; uniform vec3 horColor; varying vec3 vP;
        void main(){ float h = normalize(vP).y; gl_FragColor = vec4(mix(horColor, topColor, clamp(h*1.4+0.08, 0.0, 1.0)), 1.0); }`,
    });
    this.dome = new THREE.Mesh(this.skyGeo, this.skyMat);
    this.dome.renderOrder = -10;
    scene.add(this.dome);

    // luzes
    this.sun = new THREE.DirectionalLight(0xfff2d8, 1.35);
    this.sun.castShadow = true;
    const S = 2048;
    this.sun.shadow.mapSize.set(S, S);
    const cam = this.sun.shadow.camera;
    cam.left = -60; cam.right = 60; cam.top = 60; cam.bottom = -60; cam.near = 1; cam.far = 320;
    this.sun.shadow.bias = -0.0018;
    scene.add(this.sun); scene.add(this.sun.target);

    this.moonLight = new THREE.DirectionalLight(0x7080b8, 0.0);
    scene.add(this.moonLight);
    this.ambient = new THREE.HemisphereLight(0x6e7d8c, 0x2a2018, 0.9);
    scene.add(this.ambient);

    // sol / lua visuais
    const sunMat = new THREE.MeshBasicMaterial({ color: 0xffe8a0, fog: false });
    this.sunMesh = new THREE.Mesh(new THREE.SphereGeometry(22, 16, 12), sunMat);
    scene.add(this.sunMesh);
    const moonMat = new THREE.MeshBasicMaterial({ color: 0xdde4f5, fog: false });
    this.moonMesh = new THREE.Mesh(new THREE.SphereGeometry(14, 16, 12), moonMat);
    scene.add(this.moonMesh);

    // estrelas
    const starGeo = new THREE.BufferGeometry();
    const n = 700, sp = new Float32Array(n * 3);
    for (let i = 0; i < n; i++) {
      const v = new THREE.Vector3().setFromSphericalCoords(650, rand(0.1, 1.5), rand(0, Math.PI * 2));
      sp[i * 3] = v.x; sp[i * 3 + 1] = Math.abs(v.y); sp[i * 3 + 2] = v.z;
    }
    starGeo.setAttribute('position', new THREE.BufferAttribute(sp, 3));
    this.starMat = new THREE.PointsMaterial({ color: 0xcfd8ff, size: 1.6, sizeAttenuation: false, transparent: true, opacity: 0, fog: false });
    this.stars = new THREE.Points(starGeo, this.starMat);
    scene.add(this.stars);

    // nuvens
    this.clouds = new THREE.Group();
    const cloudMat = new THREE.MeshLambertMaterial({ color: 0xffffff, transparent: true, opacity: 0.75, flatShading: true });
    for (let i = 0; i < 14; i++) {
      const g = new THREE.Group();
      const puffs = 3 + Math.floor(rand(3));
      for (let j = 0; j < puffs; j++) {
        const s = rand(14, 30);
        const m = new THREE.Mesh(new THREE.BoxGeometry(s, s * 0.35, s * 0.7), cloudMat);
        m.position.set(rand(-24, 24), rand(-3, 3), rand(-10, 10));
        g.add(m);
      }
      g.position.set(rand(-500, 500), rand(120, 190), rand(-500, 500));
      g.userData.speed = rand(2, 5);
      this.clouds.add(g);
    }
    scene.add(this.clouds);

    // fog
    scene.fog = new THREE.FogExp2(0xa8c4d8, 0.0022 * settings.fogDensity);
    this.baseFog = 0.0022;

    // clima
    this.weather = 'clear';       // clear, rain, storm, fog, wind, snow
    this.weatherTimer = rand(60, 140);
    this.weatherTarget = 0; this.weatherAmount = 0;
    this._buildRain();
    this._lightning = 0;
  }

  _buildRain() {
    const N = 700;
    const geo = new THREE.BufferGeometry();
    const pos = new Float32Array(N * 3);
    for (let i = 0; i < N; i++) { pos[i * 3] = rand(-40, 40); pos[i * 3 + 1] = rand(0, 40); pos[i * 3 + 2] = rand(-40, 40); }
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    this.rainMat = new THREE.PointsMaterial({ color: 0x9db8d8, size: 0.22, transparent: true, opacity: 0 });
    this.rain = new THREE.Points(geo, this.rainMat);
    this.rain.frustumCulled = false;
    this.rain.visible = false;
    this.scene.add(this.rain);
    this.rainGeo = geo;
  }

  setWeather(w) {
    this.weather = w;
    this.weatherTarget = w === 'clear' ? 0 : 1;
    this.weatherTimer = w === 'storm' ? rand(40, 80) : rand(90, 200);
  }

  update(dt, playerPos) {
    // tempo
    this.time = (this.time + dt * 24 / DAY_SECONDS) % 24;
    if (this.time < dt * 24 / DAY_SECONDS) this.dayNum++;
    G.timeOfDay = this.time;

    // fase do dia
    const t = this.time;
    let key = 'day', f = 0;
    if (t < 5) { key = 'night'; f = 0; }
    else if (t < 7) { key = 'dawn'; f = 0; }
    else if (t < 8) { key = 'dawn'; f = 1 - (t - 7); }
    else if (t < 17) { key = 'day'; f = 0; }
    else if (t < 19) { key = 'dusk'; f = (t - 17) / 2; }
    else if (t < 20.5) { key = 'dusk'; f = 1; }
    else { key = 'night'; f = 0; }

    const A = SKY_PRESETS[key], B = SKY_PRESETS[key === 'dawn' ? 'day' : key === 'dusk' ? 'night' : key];
    const mix = (a, b, k) => k <= 0 ? a : b;
    const k = f;
    const mixColor = (a, b) => new THREE.Color(a).lerp(new THREE.Color(b), k);

    // sol: posição em arco
    const sunAng = ((t - 6) / 24) * Math.PI * 2; // 6h = nascer
    const sunH = Math.sin(sunAng);
    const sunDir = new THREE.Vector3(Math.cos(sunAng) * 0.5, sunH, Math.cos(sunAng) * 0.86).normalize();
    const px = playerPos.x, pz = playerPos.z, py = playerPos.y;
    this.sun.position.set(px + sunDir.x * 160, py + Math.max(8, sunDir.y * 160), pz + sunDir.z * 160);
    this.sun.target.position.set(px, py, pz);
    const dayFactor = clamp(sunH * 3, 0, 1);
    this.sun.intensity = (lerp(A.sunI, B.sunI, k)) * dayFactor + 0.05;
    this.sun.color.copy(mixColor(A.sun, B.sun));

    this.moonLight.position.set(px - sunDir.x * 160, py + Math.max(10, -sunDir.y * 160), pz - sunDir.z * 160);
    this.moonLight.target.position.set(px, py, pz);
    this.moonLight.intensity = (1 - dayFactor) * 0.22;

    this.ambient.color.copy(mixColor(A.amb, B.amb));
    this.ambient.intensity = 0.55 + 0.5 * dayFactor;

    // cúpula segue player
    this.dome.position.set(px, 0, pz);
    this.skyMat.uniforms.topColor.value.copy(mixColor(A.top, B.top));
    this.skyMat.uniforms.horColor.value.copy(mixColor(A.hor, B.hor));

    // corpos celestes
    this.sunMesh.position.set(px + sunDir.x * 560, sunDir.y * 560, pz + sunDir.z * 560);
    this.sunMesh.visible = sunDir.y > -0.1;
    this.moonMesh.position.set(px - sunDir.x * 540, -sunDir.y * 540, pz - sunDir.z * 540);
    this.moonMesh.visible = -sunDir.y > -0.1;
    this.starMat.opacity = clamp((1 - dayFactor) * 0.9 - this.weatherAmount * 0.5, 0, 0.9);
    this.stars.position.set(px, 0, pz);
    this.stars.rotation.y += dt * 0.005;

    // nuvens
    this.clouds.children.forEach(c => {
      c.position.x += c.userData.speed * dt * (1 + this.weatherAmount);
      if (c.position.x > px + 550) c.position.x = px - 550;
      if (c.position.x < px - 560) c.position.x = px + 540;
      c.position.z = c.position.z; // drift só em x
    });
    this.clouds.children.forEach(c => { c.visible = Math.abs(c.position.x - px) < 600; });

    // clima
    this.weatherTimer -= dt;
    if (this.weatherTimer <= 0) this._cycleWeather();
    this.weatherAmount = lerp(this.weatherAmount, this.weatherTarget, dt * 0.5);
    const wA = this.weatherAmount;

    // neve sempre na região congelada
    const frozen = Math.hypot(px + 380, pz + 340) < 190;
    const snowing = frozen || this.weather === 'snow';

    this.rain.visible = wA > 0.02 && (this.weather === 'rain' || this.weather === 'storm' || snowing);
    if (this.rain.visible) {
      this.rainMat.opacity = wA * 0.7;
      this.rainMat.color.setHex(snowing ? 0xffffff : 0x9db8d8);
      this.rainMat.size = snowing ? 0.5 : 0.2;
      const p = this.rainGeo.attributes.position.array;
      const fall = snowing ? 9 : 42;
      for (let i = 0; i < p.length; i += 3) {
        p[i + 1] -= fall * dt;
        if (this.weather === 'storm' && !snowing) p[i] += 8 * dt;
        if (p[i + 1] < 0) { p[i + 1] = 42; p[i] = rand(-40, 40); p[i + 2] = rand(-40, 40); }
      }
      this.rainGeo.attributes.position.needsUpdate = true;
      this.rain.position.set(px, py, pz);
    }

    // neblina variável
    let fogC = mixColor(A.fog, B.fog);
    if (wA > 0) fogC.lerp(new THREE.Color(snowing ? 0xc8d0d8 : 0x6a7a8a), wA * 0.5);
    if (this.weather === 'fog') fogC.lerp(new THREE.Color(0x9aa4a8), 0.5);
    this.scene.fog.color.copy(fogC);
    let density = this.baseFog * settings.fogDensity;
    if (this.weather === 'fog') density *= 3.2;
    else if (wA > 0.3) density *= 1.6;
    this.scene.fog.density = density;

    // relâmpagos
    if (this.weather === 'storm' && wA > 0.5) {
      this._lightning -= dt;
      if (this._lightning <= 0) {
        this._lightning = rand(3, 9);
        this.sun.intensity += 2.5;
        setTimeout(() => { this.sun.intensity = Math.max(0.05, this.sun.intensity); }, 120);
        this.onThunder?.();
      }
    }
    this.isNight = dayFactor < 0.25;
    this.dayFactor = dayFactor;
  }

  _cycleWeather() {
    const r = Math.random();
    const frozen = Math.hypot(G.player?.position.x ?? 0 + 380, (G.player?.position.z ?? 0) + 340) < 190;
    if (frozen) { this.setWeather(r < 0.6 ? 'snow' : 'clear'); return; }
    if (r < 0.45) this.setWeather('clear');
    else if (r < 0.65) this.setWeather('rain');
    else if (r < 0.78) this.setWeather('storm');
    else if (r < 0.9) this.setWeather('fog');
    else this.setWeather('wind');
  }

  get clock() {
    const h = Math.floor(this.time) % 24, m = Math.floor((this.time % 1) * 60);
    return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
  }
}

// Construtores de objetos 3D — casas, árvores, muros, baús, etc.
import * as THREE from 'three';
import { terrainHeight } from './terrain.js';
import { rand, randInt } from '../core/utils.js';

const MAT = {
  wood: new THREE.MeshLambertMaterial({ color: 0x8a5a2b }),
  woodDark: new THREE.MeshLambertMaterial({ color: 0x5e3c1c }),
  plaster: new THREE.MeshLambertMaterial({ color: 0xd8cbb0 }),
  stone: new THREE.MeshLambertMaterial({ color: 0x8d8d85 }),
  stoneDark: new THREE.MeshLambertMaterial({ color: 0x5f5f58 }),
  roof: new THREE.MeshLambertMaterial({ color: 0x9b3c2e }),
  roofBlue: new THREE.MeshLambertMaterial({ color: 0x3d6a8a }),
  leaf: new THREE.MeshLambertMaterial({ color: 0x2e7d32, flatShading: true }),
  leafDark: new THREE.MeshLambertMaterial({ color: 0x1b5e20, flatShading: true }),
  leafSnow: new THREE.MeshLambertMaterial({ color: 0xb8ccb8, flatShading: true }),
  trunk: new THREE.MeshLambertMaterial({ color: 0x6b4423 }),
  gold: new THREE.MeshLambertMaterial({ color: 0xe8c26a, emissive: 0x6a4a10 }),
  banner: new THREE.MeshLambertMaterial({ color: 0x8a2be2 }),
  banner2: new THREE.MeshLambertMaterial({ color: 0xd4af37 }),
  cloth: new THREE.MeshLambertMaterial({ color: 0xb03a48 }),
  metal: new THREE.MeshLambertMaterial({ color: 0x9aa2a8 }),
  crystal: new THREE.MeshLambertMaterial({ color: 0x8ce0ff, emissive: 0x2a6a8a, transparent: true, opacity: 0.9 }),
};

export const materials = MAT;

// ---------- Casa medieval ----------
export function makeHouse(w = 6, d = 7, h = 3.4, opts = {}) {
  const g = new THREE.Group();
  const wallMat = opts.stone ? MAT.stone : MAT.plaster;
  const wall = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), wallMat);
  wall.position.y = h / 2;
  wall.castShadow = true; wall.receiveShadow = true;
  g.add(wall);
  // estrutura de madeira
  const beam = new THREE.Mesh(new THREE.BoxGeometry(w + 0.1, 0.3, d + 0.1), MAT.woodDark);
  beam.position.y = h - 0.15; g.add(beam);
  const beamB = beam.clone(); beamB.position.y = 0.15; g.add(beamB);
  // telhado
  const roofH = h * 0.65;
  const roofGeo = new THREE.ConeGeometry(Math.hypot(w, d) * 0.62, roofH, 4);
  const roof = new THREE.Mesh(roofGeo, opts.roofMat || MAT.roof);
  roof.rotation.y = Math.PI / 4;
  roof.position.y = h + roofH / 2 - 0.1;
  roof.scale.z = d / w;
  roof.castShadow = true;
  g.add(roof);
  // porta
  const door = new THREE.Mesh(new THREE.BoxGeometry(1.1, 2, 0.15), MAT.woodDark);
  door.position.set(0, 1, d / 2 + 0.05); g.add(door);
  // janelas
  const winMat = new THREE.MeshLambertMaterial({ color: 0x223344, emissive: 0x000000 });
  for (const sx of [-w / 2 + 1.4, w / 2 - 1.4]) {
    const win = new THREE.Mesh(new THREE.BoxGeometry(0.8, 0.8, 0.1), winMat);
    win.position.set(sx, h * 0.6, d / 2 + 0.05); g.add(win);
    g.userData.windows ??= []; g.userData.windows.push(win);
  }
  g.userData.windowsMat = winMat;
  return g;
}

export function placeAt(g, x, z, rotY = 0, yOff = 0) {
  g.position.set(x, terrainHeight(x, z) + yOff, z);
  g.rotation.y = rotY;
  return g;
}

// ---------- Torre / muralha ----------
export function makeTower(h = 10, r = 3) {
  const g = new THREE.Group();
  const body = new THREE.Mesh(new THREE.CylinderGeometry(r, r * 1.15, h, 10), MAT.stone);
  body.position.y = h / 2; body.castShadow = true; body.receiveShadow = true;
  g.add(body);
  const top = new THREE.Mesh(new THREE.CylinderGeometry(r * 1.3, r * 1.3, 1.2, 10), MAT.stoneDark);
  top.position.y = h + 0.6; top.castShadow = true; g.add(top);
  for (let i = 0; i < 6; i++) {
    const m = new THREE.Mesh(new THREE.BoxGeometry(0.9, 1.2, 0.9), MAT.stoneDark);
    const a = (i / 6) * Math.PI * 2;
    m.position.set(Math.cos(a) * r * 1.1, h + 1.7, Math.sin(a) * r * 1.1);
    g.add(m);
  }
  return g;
}

export function makeWall(len = 20, h = 6, thick = 1.6) {
