  for (let i = 0; i < 6; i++) {
    const open = await page.evaluate(() => !document.getElementById('modal-layer').classList.contains('hidden'));
    if (!open) break;
    await page.mouse.click(640, 400);
    await sleep(400);
  }
  console.log('dialogs closed');

  // ---- 1. movimento ----
  const pos0 = await page.evaluate(() => ({ x: window.__G.player.root.position.x, z: window.__G.player.root.position.z }));
  await page.keyboard.down('KeyW');
  await sleep(1500);
  await page.keyboard.up('KeyW');
  const pos1 = await page.evaluate(() => ({ x: window.__G.player.root.position.x, z: window.__G.player.root.position.z }));
  const moved = Math.hypot(pos1.x - pos0.x, pos1.z - pos0.z);
