const puppeteer = require('puppeteer-core');
const http = require('http'); const fs = require('fs'); const path = require('path');
const ROOT = '/home/runner/work/PlayGround/PlayGround';
const MIME = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css' };
http.createServer((req, res) => {
  let p = decodeURIComponent(req.url.split('?')[0]); if (p === '/') p = '/index.html';
  const file = path.join(ROOT, p);
  if (!file.startsWith(ROOT) || !fs.existsSync(file) || fs.statSync(file).isDirectory()) { res.writeHead(404); res.end(); return; }
  res.writeHead(200, { 'Content-Type': MIME[path.extname(file)] || 'application/octet-stream' });
  fs.createReadStream(file).pipe(res);
}).listen(8980);
const sleep = (ms) => new Promise(r => setTimeout(r, ms));

(async () => {
  const browser = await puppeteer.launch({ executablePath: '/usr/bin/chromium', headless: 'new', args: ['--no-sandbox', '--disable-dev-shm-usage', '--use-gl=angle', '--use-angle=swiftshader'], protocolTimeout: 150000 });
  const page = await browser.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push('[pageerror] ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('[console] ' + m.text()); });
  await page.goto('http://localhost:8980/', { waitUntil: 'domcontentloaded' });
  await sleep(5000);
  await page.evaluate(() => { window.__GAME.startGame(false); });
  await sleep(2000);
  // fecha diálogos
  for (let i = 0; i < 8; i++) {
    const open = await page.evaluate(() => !document.getElementById('modal-layer').classList.contains('hidden'));
    if (!open) break;
    await page.keyboard.press('Escape');
    await sleep(300);
  }
  // estado de teste acelerado: dá elemento, magias e level
  await page.evaluate(() => {
    const G = window.__G;
    G.element = 'fogo';
    G.storyFlags.testDone = true;
    G.chapter = 5;
    for (const s of ['fogo_1', 'fogo_2', 'fogo_3', 'fogo_4']) G.spells[s] = { level: 1, uses: 0 };
    G.grimoire.appear();
    G.story.recalcStats();
    G.hp = G.maxHp; G.mp = G.maxMp;
    G.quests.offer('main_dungeon');
  });

  // ---- 1. magia: conjura fogo_1 perto de inimigo ----
  await page.evaluate(() => { window.__G.story.fastTravel(230, 60); }); // floresta (goblins)
  await sleep(4000);
  const enemies0 = await page.evaluate(() => window.__G.enemies.active.filter(e => !e.dead).length);
  const cast1 = await page.evaluate(() => { window.__G.magic.castSlot(1); return window.__G.mp; });
  await sleep(2500);
  const killsAfterSpell = await page.evaluate(() => ({
    mp: Math.round(window.__G.mp),
    dead: window.__G.enemies.active.filter(e => e.dead).length,
    total: window.__G.enemies.active.length,
  }));
  console.log('MAGIC enemies=', enemies0, JSON.stringify(killsAfterSpell));

  // ---- 2. dungeon ----
  await page.evaluate(() => { window.__G.story.fastTravel(150, 200); });
  await sleep(2000);
  const inter0 = await page.evaluate(() => window.__GAME.interactTarget && window.__GAME.interactTarget.type);
  console.log('cave interact=', inter0);
  await page.keyboard.press('KeyE');
  await sleep(3000);
  const dung = await page.evaluate(() => ({
    active: window.__G.dungeon.active,
    enemies: window.__G.enemies.active.filter(e => !e.dead).length,
    boss: !!(window.__G.dungeon.boss && !window.__G.dungeon.boss.dead),
  }));
  console.log('DUNGEON', JSON.stringify(dung));
  await page.screenshot({ path: '/tmp/opencode/shot_dungeon.jpg', type: 'jpeg', quality: 60 });
  // boss bar visível?
  const bossBar = await page.evaluate(() => !document.getElementById('boss-bar').classList.contains('hidden'));
  console.log('bossbar visible=', bossBar);
  // mata o boss via dano direto (valida cadeia morte→quest→saída)
  await page.evaluate(() => { window.__G.dungeon.boss.takeDamage(99999, { heavy: true }); });
  await sleep(6000);
  const afterBoss = await page.evaluate(() => ({
    questDone: window.__G.quests.doneIds.includes('main_dungeon'),
    active: window.__G.dungeon.active,
  }));
  console.log('AFTER BOSS', JSON.stringify(afterBoss));

  // ---- 3. save / load ----
  await page.evaluate(() => { window.__G.gold = 1234; window.__G.level = 7; window.__G.story.recalcStats(); });
  const saved = await page.evaluate(() => { window.__GAME.save(); return JSON.parse(localStorage.getItem('aetheria_save') || 'null'); });
  console.log('SAVE has gold=', saved && saved.gold, 'level=', saved && saved.level);
  await page.reload({ waitUntil: 'domcontentloaded' });
  await sleep(5000);
  await page.evaluate(() => { window.__GAME.startGame(true); });
  await sleep(2500);
  const loaded = await page.evaluate(() => ({ gold: window.__G.gold, level: window.__G.level, element: window.__G.element, chapter: window.__G.chapter }));
  console.log('LOADED', JSON.stringify(loaded));

  await page.screenshot({ path: '/tmp/opencode/shot_final.jpg', type: 'jpeg', quality: 60 });
  console.log('--- ERRORS ---');
  errors.slice(0, 20).forEach(e => console.log(e));
  if (!errors.length) console.log('(nenhum)');
  await browser.close(); process.exit(0);
})().catch(e => { console.error('FAIL', e); process.exit(1); });

