104:   castSlot(slot, opts = {}) {
105:     if (!G.element) { G.hud?.hint('Você ainda não possui elemento.'); return false; }
106:     const spell = getSpellDef(G.element, slot);
107:     if (!spell) return false;
108:     const known = G.spells[spell.id];
109:     if (!known) { G.hud?.hint(`Magia bloqueada: desbloqueia no nível ${spell.unlock}.`); return false; }
110:     const cd = this.cooldowns[spell.id] || 0;
111:     if (cd > 0) { G.hud?.hint('Recarregando…'); return false; }
112:     const manaCost = spell.mana * (1 - Math.min(0.3, (G.attributes.mana - 5) * 0.01));
113:     if (G.mp < manaCost) { G.hud?.hint('Mana insuficiente!'); return false; }
114:     if (G.player.dead) return false;
115: 
116:     const pl = G.player;
117:     if (['attack', 'heavy', 'dodge'].includes(pl.state)) return false;
118: 
119:     G.mp -= manaCost;
120:     this.cooldowns[spell.id] = spell.cd;
121:     known.uses++;
122:     // evolução da magia: a cada 25 usos sobe de nível (até 5)
123:     if (known.uses % 25 === 0 && known.level < 5) {
124:       known.level++;
125:       G.hud?.floatText?.(`${spell.name} nível ${known.level}!`, pl.root.position, '#ffe633');
126:       audio.sfx('levelup');
127:       G.grimoire?.refresh();
128:     }
129: 
130:     const camDir = _dir.set(0, 0, -1).applyQuaternion(G.camera.quaternion);
131:     const origin = new THREE.Vector3(pl.root.position.x, pl.root.position.y + 1.4, pl.root.position.z);
132:     pl.state = 'cast'; pl.stateT = 0;
133:     pl.actionYaw = Math.atan2(camDir.x, camDir.z);
134:     audio.sfx('magicCast', { element: G.element });
135:     const color = ELEMENTS[G.element].color;
136: 
137:     switch (spell.type) {
138:       case 'projectile': this._castProjectile(spell, origin, camDir, color, true); break;
139:       case 'beam': this._castBeam(spell, origin, camDir, color); break;
140:       case 'chain': this._castChain(spell, origin, color); break;
141:       case 'nova': this._castNova(spell, origin, color); break;
142:       case 'rain': this._castRain(spell, origin, camDir, color); break;
143:       case 'meteor': this._castMeteor(spell, origin, camDir, color); break;
144:       case 'dash': case 'windDash': this._castDash(spell, camDir, color); break;
145:       case 'spikes': this._castSpikes(spell, origin, camDir, color); break;
146:       case 'quake': this._castQuake(spell, origin, color); break;
147:       case 'storm': this._castStorm(spell, origin, camDir, color); break;
148:       case 'prison': this._castPrison(spell, origin, camDir, color); break;
149:       case 'tornado': this._castTornado(spell, origin, camDir, color); break;
150:     }
151:     G.hud?.flashSlot(slot);
152:     return true;
153:   }
