182:       // preditivo leve
183:       dir.y += 0.02;
184:       dir.normalize();
185:     }
186:     p.vx = dir.x * spell.speed; p.vy = dir.y * spell.speed; p.vz = dir.z * spell.speed;
187:     this.projectiles.push(p);
188:     const c = ELEMENT_COLORS[G.element];
189:     effects.particles.burst(origin.x, origin.y, origin.z, 10, { r: c.r, g: c.g, b: c.b, spread: 1, up: 0.5, life: 0.3, size: 0.3 });
