192:   _castBeam(spell, origin, camDir, color) {
193:     const aim = this._aimPoint(origin, camDir, spell.range);
194:     const end = aim.point;
195:     // linha de raio
196:     const geo = new THREE.BufferGeometry().setFromPoints([origin, end]);
197:     const line = new THREE.Line(geo, new THREE.LineBasicMaterial({ color, transparent: true, opacity: 0.9 }));
198:     G.scene.add(line);
199:     this.areas.push({ t: 0, duration: 0.12, mesh: line });
200:     const dist = origin.distanceTo(end);
201:     for (let i = 0; i < 5; i++) {
202:       const t = i / 5;
203:       effects.hit(origin.x + (end.x - origin.x) * t, origin.y + (end.y - origin.y) * t, origin.z + (end.z - origin.z) * t, color, 4, 0.3);
204:     }
205:     audio.sfx('thunder');
206:     const dmg = this.spellDamage(spell);
207:     if (aim.enemy) aim.enemy.takeDamage(dmg, { element: 'raio', source: 'magic', crit: Math.random() < 0.25 });
208:     else this._areaDamage(end.x, end.z, 1.5, dmg * 0.6, 'raio', spell);
209:     G.camCtl.shakeIt(0.3);
