212:   _castChain(spell, origin, color) {
213:     const aim = this._aimPoint(origin, camDir(), spell.range);
214:     let cur = aim.enemy;
215:     if (!cur) { this._castBeam({ ...spell, range: spell.range }, origin, camDir(), color); return; }
216:     const hitSet = new Set();
217:     let from = origin.clone();
218:     let jumps = spell.jumps + Math.floor(G.attributes.poder / 10);
219:     for (let j = 0; j < jumps && cur; j++) {
220:       const to = new THREE.Vector3(cur.root.position.x, cur.root.position.y + 0.8, cur.root.position.z);
221:       const geo = new THREE.BufferGeometry().setFromPoints([from, to]);
222:       const line = new THREE.Line(geo, new THREE.LineBasicMaterial({ color, transparent: true, opacity: 0.9 }));
223:       G.scene.add(line);
224:       this.areas.push({ t: 0, duration: 0.15, mesh: line });
225:       cur.takeDamage(this.spellDamage(spell) * (1 - j * 0.15), { element: 'raio', source: 'magic', crit: Math.random() < 0.2 });
226:       audio.sfx('thunder');
227:       hitSet.add(cur);
228:       // próximo alvo
229:       const enemies = G.enemies ? G.enemies.active : [];
230:       let next = null, nd = spell.range;
231:       for (const e of enemies) {
232:         if (e.dead || hitSet.has(e)) continue;
233:         const d = e.root.position.distanceTo(cur.root.position);
234:         if (d < nd) { nd = d; next = e; }
235:       }
236:       from = to.clone();
237:       cur = next;
238:     }
239:   }
