453:   _burn(x, z, radius, seconds) {
454:     // queimadura: dano contínuo
455:     const area = {
456:       t: 0, duration: seconds,
457:       update: (dt) => {
458:         if (Math.random() < dt * 4) this._areaDamage(x, z, radius, 3, 'fogo', null, 0, true);
