const sleep = (ms) => new Promise(r => setTimeout(r, ms));

(async () => {
  const browser = await puppeteer.launch({ executablePath: '/usr/bin/chromium', headless: 'new', args: ['--no-sandbox', '--disable-dev-shm-usage', '--use-gl=angle', '--use-angle=swiftshader'], protocolTimeout: 150000 });
  const page = await browser.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push('[pageerror] ' + e.message));
  await page.goto('http://localhost:8983/', { waitUntil: 'domcontentloaded' });
  await sleep(5000);
  await page.evaluate(() => { window.__GAME.startGame(false); });
  await sleep(2000);
  await page.evaluate(() => { window.__G.ui.endDialog?.(); });
  await sleep(500);
  await page.evaluate(() => {
    const G = window.__G;
    G.element = 'fogo';
    for (const s of ['fogo_1', 'fogo_2', 'fogo_3', 'fogo_4']) G.spells[s] = { level: 1, uses: 0 };
    G.grimoire.appear();
    G.story.recalcStats(); G.hp = G.maxHp; G.mp = G.maxMp;
  });

  await page.evaluate(async () => {
    const THREE = (await import('../vendor/three.module.js'));
    const G = window.__G;
    const cam = G.camCtl.camera;
    const fwd = new THREE.Vector3(); cam.getWorldDirection(fwd); fwd.y = 0; fwd.normalize();
    const p = G.player.root.position;
    const e = G.enemies.spawnAt({ type: 'goblin', rank: 'E' }, p.x + fwd.x * 6, p.z + fwd.z * 6);
    e.state = 'idle'; e.detectRange = 0;
    window.__enemy = e;
  });
  await sleep(1500);
  const pre = await page.evaluate(() => ({
    paused: window.__G.paused,
    enemyPos: window.__enemy.root.position.toArray().map(v => +v.toFixed(1)),
    plPos: window.__G.player.root.position.toArray().map(v => +v.toFixed(1)),
    camPos: window.__G.camCtl.camera.position.toArray().map(v => +v.toFixed(1)),
    state: window.__G.player.state,
  }));
  console.log('PRE', JSON.stringify(pre));
  const castRes = await page.evaluate(() => window.__G.magic.castSlot(1));
  console.log('cast returned', castRes);
  for (let i = 0; i < 5; i++) {
    await sleep(400);
    const s = await page.evaluate(() => ({
      proj: window.__G.magic.projectiles.map(p => p.mesh.position.toArray().map(v => +v.toFixed(1))),
      enemyHp: Math.round(window.__enemy.hp),
      v: window.__G.magic.projectiles.map(p => [+p.vx.toFixed(1), +p.vy.toFixed(1), +p.vz.toFixed(1)]),
    }));
    console.log('t+' + (i * 0.4), JSON.stringify(s));
  }
  console.log('--- ERRORS ---');
  errors.slice(0, 10).forEach(e => console.log(e));
  if (!errors.length) console.log('(nenhum)');
  await browser.close(); process.exit(0);
})().catch(e => { console.error('FAIL', e); process.exit(1); });

