    await sleep(5000);
    const s = await page.evaluate(() => {
      const G = window.__G;
      const st = G.story.invasionState;
      const inv = G.enemies.active.filter(e => e.invasion && !e.dead);
      return {
        wave: st ? st.wave : null, t: st ? +st.t.toFixed(1) : null,
        alive: inv.length, total: G.enemies.active.filter(e => !e.dead).length,
        hp: Math.round(G.hp), quest: G.quests.activeIds.includes('main_invasao'),
