const puppeteer = require('puppeteer-core');
const http = require('http'); const fs = require('fs'); const path = require('path');
const ROOT = '/home/runner/work/PlayGround/PlayGround';
const MIME = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css' };
http.createServer((req, res) => {
  let p = decodeURIComponent(req.url.split('?')[0]); if (p === '/') p = '/index.html';
  const file = path.join(ROOT, p);
  if (!file.startsWith(ROOT) || !fs.existsSync(file) || fs.statSync(file).isDirectory()) { res.writeHead(404); res.end(); return; }
  res.writeHead(200, { 'Content-Type': MIME[path.extname(file)] || 'application/octet-stream' });
  fs.createReadStream(file).pipe(res);
}).listen(8990);
const sleep = (ms) => new Promise(r => setTimeout(r, ms));
const until = async (fn, ms = 90000) => { const t0 = Date.now(); while (Date.now() - t0 < ms) { if (await page.evaluate(fn)) return true; await sleep(1500); } return false; };

let page;
(async () => {
  const browser = await puppeteer.launch({ executablePath: '/usr/bin/chromium', headless: 'new', args: ['--no-sandbox', '--disable-dev-shm-usage', '--use-gl=angle', '--use-angle=swiftshader'], protocolTimeout: 240000 });
  page = await browser.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push('[pageerror] ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('[console] ' + m.text()); });
  await page.setViewport({ width: 1280, height: 720 });
  await page.goto('http://localhost:8990/', { waitUntil: 'domcontentloaded' });
  await sleep(5000);
  await page.evaluate(() => { window.__GAME.startGame(false); });
  await sleep(2500);
  await page.keyboard.press('Escape'); await sleep(600);
  await page.evaluate(() => { window.__G.quests.offer('main_teste'); window.__G.story.fastTravel(0, -309); });
  await sleep(2000);
  await page.keyboard.press('KeyE');

  // espera a cinemática terminar (poll)
  const done = await until(() => window.__G.storyFlags.testDone === true, 150000);
  const st1 = await page.evaluate(() => ({
    element: window.__G.element, grimoire: window.__G.grimoire.visible,
    spell1: Object.keys(window.__G.spells), paused: window.__G.paused,
    pl: window.__G.player.root.position.toArray().map(v => +v.toFixed(0)),
  }));
