const puppeteer = require('puppeteer-core');
const http = require('http'); const fs = require('fs'); const path = require('path');
const ROOT = '/home/runner/work/PlayGround/PlayGround';
const MIME = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css' };
http.createServer((req, res) => {
  let p = decodeURIComponent(req.url.split('?')[0]); if (p === '/') p = '/index.html';
  const file = path.join(ROOT, p);
  if (!file.startsWith(ROOT) || !fs.existsSync(file) || fs.statSync(file).isDirectory()) { res.writeHead(404); res.end(); return; }
  res.writeHead(200, { 'Content-Type': MIME[path.extname(file)] || 'application/octet-stream' });
  fs.createReadStream(file).pipe(res);
}).listen(8991);
const sleep = (ms) => new Promise(r => setTimeout(r, ms));
let page;
const until = async (fn, ms = 30000) => { const t0 = Date.now(); while (Date.now() - t0 < ms) { if (await page.evaluate(fn)) return true; await sleep(1200); } return false; };

(async () => {
  const browser = await puppeteer.launch({ executablePath: '/usr/bin/chromium', headless: 'new', args: ['--no-sandbox', '--disable-dev-shm-usage', '--use-gl=angle', '--use-angle=swiftshader'], protocolTimeout: 240000 });
  page = await browser.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push('[pageerror] ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('[console] ' + m.text()); });
  await page.setViewport({ width: 1280, height: 720 });
  await page.goto('http://localhost:8991/', { waitUntil: 'domcontentloaded' });
  await sleep(5000);
  await page.evaluate(() => { window.__GAME.startGame(false); });
  await sleep(2500);
  await page.keyboard.press('Escape'); await sleep(600);

  // simula fim da masmorra (progresso médio do jogo)
  await page.evaluate(() => {
    const G = window.__G;
    G.storyFlags.testDone = true; G.chapter = 5;
    G.story.recalcStats(); G.hp = G.maxHp; G.mp = G.maxMp;
    G.quests.doneIds.push('main_dungeon'); G.quests.progress['main_dungeon'] = { enter: 1, boss: 1 };
    G.quests.onQuestComplete('main_dungeon');
  });

  // espera oferta da main_final
  const offered = await until(() => window.__G.quests.activeIds.includes('main_final'), 15000);
  console.log('main_final offered=', offered);

  // viaja ao Pico Umbral e se aproxima
  await page.evaluate(() => { window.__G.story.fastTravel(360, -240); });
  const spawn = await until(() => window.__G.story.finalState && window.__G.story.finalState.spawned, 25000);
  const morg = await page.evaluate(() => {
    const m = window.__G.story.morgath;
    return m ? { hp: m.maxHp, name: m.type.name, pos: m.root.position.toArray().map(v => +v.toFixed(0)) } : null;
  });
  console.log('MORGATH spawned=', spawn, JSON.stringify(morg));
  await sleep(2500);
  await page.screenshot({ path: '/tmp/opencode/shot_morgath.jpg', type: 'jpeg', quality: 65 });

  // mata Morgath
  await page.evaluate(() => { window.__G.story.morgath.takeDamage(99999, { heavy: true }); });
  const ended = await until(() => !!document.getElementById('ending-screen'), 15000);
  const end = await page.evaluate(() => ({
    questDone: window.__G.quests.doneIds.includes('main_final'),
    screen: !!document.getElementById('ending-screen'),
    level: window.__G.level, gold: window.__G.gold,
    chapter: window.__G.chapter,
  }));
  console.log('ENDING shown=', ended, JSON.stringify(end));
  await sleep(1500);
  await page.screenshot({ path: '/tmp/opencode/shot_ending.jpg', type: 'jpeg', quality: 65 });

  // botão continuar
  await page.click('#ending-continue');
  await sleep(800);
  const cont = await page.evaluate(() => ({
    screenGone: !document.getElementById('ending-screen'),
    paused: window.__G.paused,
  }));
  console.log('CONTINUE', JSON.stringify(cont));
  await page.screenshot({ path: '/tmp/opencode/shot_after.jpg', type: 'jpeg', quality: 65 });

  console.log('--- ERRORS ---');
  errors.slice(0, 10).forEach(e => console.log(e));
  if (!errors.length) console.log('(nenhum)');
  await browser.close(); process.exit(0);
})().catch(e => { console.error('FAIL', e); process.exit(1); });

