168:   // ---------- ciclo ----------
169:   update(dt, camera) {
170:     this.stateT += dt;
171:     this.animPhase += dt * (4 + this.speed * 0.7);
172:     this.iframe = Math.max(0, this.iframe - dt);
173:     this.comboTimer = Math.max(0, this.comboTimer - dt);
174:     this.staggered = Math.max(0, this.staggered - dt);
175:     this.hurtFlash = Math.max(0, this.hurtFlash - dt * 2);
176:     if (this.comboTimer === 0 && this.comboIdx > 0 && this.state !== 'attack') this.comboIdx = 0;
177: 
178:     const busy = ['attack', 'cast', 'dodge', 'heavy', 'hurt', 'dead', 'interact', 'crystal'].includes(this.state);
179: 
180:     // ---- entrada de movimento ----
181:     const mv = readMove();
182:     const canMove = !this.dead && this.staggered <= 0 && !['attack', 'cast', 'dodge', 'heavy', 'interact', 'crystal'].includes(this.state);
183:     let moveSpeed = 0;
184:     if (canMove) {
185:       // direção relativa à câmera
186:       const len = Math.hypot(mv.x, mv.z);
187:       if (len > 0.05) {
188:         const d = _v1.set(0, 0, -1).applyQuaternion(camera.quaternion); d.y = 0; d.normalize();
189:         const right = _v2.set(1, 0, 0).applyQuaternion(camera.quaternion); right.y = 0; right.normalize();
190:         const wx = right.x * mv.x + d.x * (-mv.z);
191:         const wz = right.z * mv.x + d.z * (-mv.z);
192:         const wl = Math.hypot(wx, wz) || 1;
193:         const sprint = input.sprint && G.stamina > 5;
194:         const base = 4.2 + (G.attributes.velocidade - 5) * 0.12;
195:         const waterSlow = this.inWater ? 0.55 : 1;
196:         moveSpeed = (sprint ? base * 1.55 : base) * waterSlow;
197:         this._wishX = (wx / wl) * moveSpeed;
198:         this._wishZ = (wz / wl) * moveSpeed;
199:         this._wishYaw = Math.atan2(wx, wz);
200:         if (sprint && this.grounded) {
201:           G.stamina = Math.max(0, G.stamina - dt * 14);
202:           this.state = 'sprint';
203:         } else {
204:           this.state = 'run';
205:         }
206:       } else {
207:         this._wishX = this._wishZ = 0;
208:         this.state = this.dead ? 'dead' : 'idle';
209:       }
210:       // bloquear
211:       this.blocking = input.block && G.stamina > 10 && this.grounded && !this.dead;
212:       // pular
213:       if ((wasPressed('Space') || touchPressed('jump')) && this.grounded) {
214:         this.vel.y = 7.2;
215:         this.grounded = false;
216:         this.state = 'jump';
217:         audio.sfx('jump');
218:       }
219:       // esquiva
220:       if ((wasPressed('KeyC') || touchPressed('dodge')) && G.stamina >= 25 && this.grounded && !this.dead) {
221:         this.startDodge();
222:       }
223:     } else {
224:       this._wishX = this._wishZ = 0;
225:       if (this.state === 'run' || this.state === 'sprint' || this.state === 'idle') this.state = 'idle';
226:       this.blocking = false;
227:     }
228:     if (this.blocking) G.stamina = Math.max(0, G.stamina - dt * 8);
229:     else if (this.grounded) G.stamina = Math.min(G.maxStamina, G.stamina + dt * (input.sprint ? 4 : 12));
230: 
231:     // ---- física ----
232:     this.inWater = this.isInWaterBody();
233:     this.speed = Math.hypot(this._wishX || 0, this._wishZ || 0);
234:     let vx = this._wishX || 0, vz = this._wishZ || 0;
235:     // empurrão de knockback
236:     vx += this._kbx || 0; vz += this._kbz || 0;
237:     this._kbx = (this._kbx || 0) * Math.pow(0.001, dt); this._kbz = (this._kbz || 0) * Math.pow(0.001, dt);
238: 
239:     // esquiva: impulso próprio
240:     if (this.state === 'dodge') {
241:       const t = this.stateT / 0.45;
242:       const boost = Math.sin(Math.min(1, t) * Math.PI) * 9;
243:       vx += Math.sin(this.yaw) * boost; vz += Math.cos(this.yaw) * boost;
244:     }
245: 
246:     this.vel.y -= 20 * dt;
247:     let nx = this.root.position.x + vx * dt;
248:     let nz = this.root.position.z + vz * dt;
249:     let ny = this.root.position.y + this.vel.y * dt;
250: 
251:     // colisão com o mundo
252:     const res = this.world.resolveMove(this.root.position.x, this.root.position.z, nx, nz, 0.55);
253:     nx = res.x; nz = res.z;
254: 
255:     const ground = terrainHeight(nx, nz);
256:     if (ny <= ground) {
257:       if (!this.grounded && this.vel.y < -6) audio.sfx('land');
258:       ny = ground; this.vel.y = 0; this.grounded = true;
259:       if (this.state === 'jump' || this.state === 'fall') this.state = 'idle';
260:     } else {
261:       this.grounded = false;
262:       if (this.vel.y < -0.5 && this.state !== 'jump') this.state = 'fall';
263:     }
264: 
265:     this.root.position.set(nx, ny, nz);
266:     G.savePos = { x: nx, z: nz };
267: 
268:     // girar corpo
269:     if (this.state === 'attack' || this.state === 'heavy' || this.state === 'cast') {
270:       // olha para o alvo / direção da câmera
271:       const targetYaw = this.actionYaw ?? this.yaw;
272:       this.yaw = angleLerp(this.yaw, targetYaw, Math.min(1, dt * 14));
273:     } else if (this.speed > 0.5) {
274:       this.yaw = angleLerp(this.yaw, this._wishYaw ?? this.yaw, Math.min(1, dt * 12));
275:     }
276:     this.root.rotation.y = this.yaw;
277: 
278:     // ---- passos (som) ----
279:     if (this.grounded && this.speed > 1 && this.state !== 'dodge') {
280:       this.stepTimer -= dt * (this.state === 'sprint' ? 2.4 : 1.6);
281:       if (this.stepTimer <= 0) { this.stepTimer = 0.5; audio.sfx('step'); }
282:     }
283: 
284:     // ---- ataque ----
285:     if (!this.dead && this.staggered <= 0) {
286:       this.handleAttack(dt, camera);
287:       this.handleSpells();
288:     }
289:     if (this.state === 'attack') this.updateAttackPose();
290:     if (this.state === 'interact' && this.stateT > 0.6) this.state = 'idle';
291: 
292:     // ---- pose ----
293:     this.updatePose(dt);
294:     this.root.traverse(o => { if (o.isMesh) { } });
295:   }
