312:   handleAttack(dt, camera) {
313:     // carregar pesado segurando
314:     const held = input.buttons.left || touchHeld('attack');
315:     if (held && (this.state === 'idle' || this.state === 'run' || this.state === 'sprint')) {
316:       this.chargeT += dt;
317:       if (this.chargeT > 0.45 && this.grounded && G.stamina >= 30) {
318:         // inicia pesado
319:         this.startAttack('heavy');
320:         this.chargeT = 0;
321:       }
322:     } else {
323:       if (this.chargeT > 0 && this.chargeT < 0.45) {
324:         // clique curto: combo
325:         if ((this.state === 'idle' || this.state === 'run' || this.state === 'sprint') && this.grounded) {
326:           this.startAttack('combo');
327:         }
328:       }
329:       this.chargeT = 0;
330:     }
331:     if (wasPressed('KeyQ') && this.grounded && this.stamina >= 30 &&
332:       (this.state === 'idle' || this.state === 'run' || this.state === 'sprint')) {
333:       this.startAttack('heavy');
334:     }
335: 
336:     if (this.state === 'attack' || this.state === 'heavy') {
337:       const dur = this.state === 'heavy' ? 0.75 : 0.42;
338:       const hitAt = this.state === 'heavy' ? 0.38 : (0.14 + this.comboIdx * 0.02);
339:       if (!this.attackHitDone && this.stateT >= hitAt) {
340:         this.attackHitDone = true;
341:         this.doMeleeHit(this.state === 'heavy');
342:       }
343:       if (this.stateT >= dur) {
344:         this.state = 'idle'; this.stateT = 0;
345:       }
346:     }
347:   }
