374:   doMeleeHit(heavy) {
375:     const dirX = Math.sin(this.yaw), dirZ = Math.cos(this.yaw);
376:     const reach = heavy ? 3.2 : 2.6;
377:     const dmgBase = 6 + G.attributes.forca * 1.2 + (G.equipment.weapon ? G.equipment.weapon.dmg : 0);
378:     const dmg = dmgBase * (heavy ? 2.1 : 1) * rand(0.85, 1.15);
379:     const crit = Math.random() < 0.05 + G.attributes.critico * 0.012;
380:     let hitAny = false;
381:     const enemies = G.enemies ? G.enemies.active : [];
382:     for (const e of enemies) {
383:       if (e.dead) continue;
384:       const dx = e.root.position.x - this.root.position.x;
385:       const dz = e.root.position.z - this.root.position.z;
386:       const d = Math.hypot(dx, dz);
387:       if (d > reach + e.radius) continue;
388:       const dot = (dx / d) * dirX + (dz / d) * dirZ;
389:       if (dot < 0.3) continue;
390:       hitAny = true;
391:       e.takeDamage(dmg * (crit ? 2 : 1), {
392:         x: dirX, z: dirZ, kb: heavy ? 6 : 3, crit, heavy,
393:         element: null, source: 'player',
394:       });
395:     }
396:     // rastro da lâmina
397:     const hx = this.root.position.x + dirX * 1.2;
398:     const hz = this.root.position.z + dirZ * 1.2;
399:     const hy = this.root.position.y + 1.1;
400:     const c = heavy ? 0xffe0a0 : 0xcfd8e2;
401:     effects.particles.burst(hx, hy, hz, heavy ? 10 : 6,
402:       { r: 0.85, g: 0.88, b: 0.95, spread: 1.6, up: 0.2, life: 0.25, size: 0.3, drag: 0.8 });
403:     if (hitAny) audio.sfx(crit ? 'crit' : 'hit');
404:     if (heavy) {
405:       G.combatMusic = 5;
406:     }
407:   }
