419:   // ---------- animação procedural ----------
420:   updatePose(dt) {
421:     const t = this.animPhase;
422:     const st = this.state;
423:     const speedF = clamp(this.speed / 6, 0, 1);
424:     const A = this.arms, L = this.legs;
425: 
426:     // padrão: reset suave
427:     const ease = (cur, target, k) => damp(cur, target, k, dt);
428:     let lHip = 0, rHip = 0, lKnee = 0, rKnee = 0;
429:     let lSh = -0.1, rSh = -0.1, lEl = -0.25, rEl = -0.25;
430:     let torsoRot = 0, headRot = 0, bob = 0, lean = 0;
431: 
432:     if (st === 'idle') {
433:       const b = Math.sin(t * 1.6) * 0.03;
434:       bob = b * 0.4;
435:       lSh = -0.08 + b; rSh = -0.08 - b;
436:       lEl = -0.3; rEl = -0.3;
437:       torsoRot = Math.sin(t * 0.8) * 0.02;
438:       headRot = Math.sin(t * 0.5) * 0.06;
439:     } else if (st === 'run' || st === 'sprint') {
440:       const f = st === 'sprint' ? t * 1.4 : t;
441:       const amp = st === 'sprint' ? 0.95 : 0.7;
442:       lHip = Math.sin(f) * amp; rHip = -Math.sin(f) * amp;
443:       lKnee = Math.max(0, -Math.sin(f) * amp * 0.9);
444:       rKnee = Math.max(0, Math.sin(f) * amp * 0.9);
445:       lSh = -0.2 + Math.sin(f + Math.PI) * amp * 0.7;
446:       rSh = -0.2 + Math.sin(f) * amp * 0.7;
447:       lEl = -0.5 - Math.max(0, Math.sin(f + Math.PI)) * 0.4;
448:       rEl = -0.5 - Math.max(0, Math.sin(f)) * 0.4;
449:       torsoRot = Math.sin(f * 2) * 0.04;
450:       lean = st === 'sprint' ? 0.24 : 0.12;
451:       bob = Math.abs(Math.sin(f)) * 0.06;
452:     } else if (st === 'jump') {
453:       lHip = -0.5; rHip = 0.3; lKnee = 0.9; rKnee = 0.4;
454:       lSh = -2.6; rSh = -2.6; lEl = -0.3; rEl = -0.3;
455:     } else if (st === 'fall') {
456:       lHip = -0.3; rHip = 0.2; lKnee = 0.6; rKnee = 0.5;
457:       lSh = -1.4 + Math.sin(t * 6) * 0.2; rSh = -1.2 - Math.sin(t * 6) * 0.2;
458:     } else if (st === 'dodge') {
459:       const p = clamp(this.stateT / 0.45, 0, 1);
460:       const spin = p * Math.PI * 2;
461:       this.root.rotation.x = spin;
462:       lHip = -1.2; rHip = -0.4; lKnee = 1.8; rKnee = 1.2;
463:       lSh = -1.8; rSh = -1.8; lEl = -1.2; rEl = -1.2;
464:       if (p >= 1) this.root.rotation.x = 0;
465:     } else if (st === 'attack') {
466:       const p = clamp(this.stateT / 0.42, 0, 1);
467:       const wind = Math.min(1, p * 2.4), strike = clamp((p - 0.35) * 2.6, 0, 1);
468:       const c = this.comboIdx;
469:       if (c === 1) { rSh = -2.4 * wind + (strike * 2.4) - 0.4; rEl = -1.4 + strike * 1.0; lSh = -0.5 * wind; }
470:       else if (c === 2) { rSh = -0.6 - strike * 1.8; rEl = -0.4; lSh = -2.2 * wind + strike * 1.6; torsoRot = strike * 0.5 * (wind - 0.5); }
471:       else { rSh = -2.8 * wind + strike * 2.2 - 0.6; rEl = -1.2 + strike * 0.8; lSh = -0.4; torsoRot = -0.3 + strike * 0.6; }
472:       lHip = 0.25 * strike; rHip = -0.2 * strike;
473:       lean = 0.15 * strike;
474:     } else if (st === 'heavy') {
475:       const p = clamp(this.stateT / 0.75, 0, 1);
476:       const wind = Math.min(1, p * 1.8), strike = clamp((p - 0.45) * 3.2, 0, 1);
477:       rSh = -3.0 * wind + strike * 2.8 - 0.5;
478:       rEl = -1.6 + strike * 1.4;
479:       lSh = -1.0 * wind;
480:       torsoRot = -0.5 * wind + strike * 0.9;
481:       lean = 0.2 + strike * 0.25;
482:       lHip = 0.3 * strike; rHip = -0.25 * strike;
483:       if (wind >= 1 && strike === 0) {
484:         // partículas de carga
485:         if (Math.random() < dt * 20) {
486:           effects.particles.emit({ x: this.root.position.x + rand(-0.4, 0.4), y: this.root.position.y + 1.2, z: this.root.position.z + rand(-0.4, 0.4), vy: 1, life: 0.3, size: 0.25, r: 1, g: 0.9, b: 0.6 });
487:         }
488:       }
489:     } else if (st === 'cast') {
490:       const p = clamp(this.stateT / 0.5, 0, 1);
