const puppeteer = require('puppeteer-core');
const http = require('http'); const fs = require('fs'); const path = require('path');
const ROOT = '/home/runner/work/PlayGround/PlayGround';
const MIME = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css' };
http.createServer((req, res) => {
  let p = decodeURIComponent(req.url.split('?')[0]); if (p === '/') p = '/index.html';
  const file = path.join(ROOT, p);
  if (!file.startsWith(ROOT) || !fs.existsSync(file) || fs.statSync(file).isDirectory()) { res.writeHead(404); res.end(); return; }
  res.writeHead(200, { 'Content-Type': MIME[path.extname(file)] || 'application/octet-stream' });
  fs.createReadStream(file).pipe(res);
}).listen(8993);
const sleep = (ms) => new Promise(r => setTimeout(r, ms));

(async () => {
  const browser = await puppeteer.launch({ executablePath: '/usr/bin/chromium', headless: 'new', args: ['--no-sandbox', '--disable-dev-shm-usage', '--use-gl=angle', '--use-angle=swiftshader'], protocolTimeout: 180000 });
  const page = await browser.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push('[pageerror] ' + e.message));
  await page.setViewport({ width: 1280, height: 720 });
  await page.goto('http://localhost:8993/', { waitUntil: 'domcontentloaded' });
  await sleep(5000);
  await page.evaluate(() => { window.__GAME.startGame(false); });
  await sleep(2500);
  await page.keyboard.press('Escape'); await sleep(600);
  await page.evaluate(() => {
    const G = window.__G;
    G.element = 'fogo';
    G.spells['fogo_1'] = { level: 1, uses: 0 };
    G.story.recalcStats(); G.mp = G.maxMp;
  });

  // --- teste 1: ataque melee, estados ao longo do tempo ---
  const states = [];
  await page.mouse.move(640, 400);
  await page.mouse.down(); await sleep(60); await page.mouse.up();
  for (let i = 0; i < 10; i++) {
    await sleep(200);
    const s = await page.evaluate(() => ({ st: window.__G.player.state, t: +window.__G.player.stateT.toFixed(2) }));
    states.push(s.st);
  }
  console.log('MELEE states:', states.join(','));

  // tenta mover depois do ataque
  const p0 = await page.evaluate(() => window.__G.player.root.position.x);
  await page.keyboard.down('KeyW'); await sleep(1000); await page.keyboard.up('KeyW');
  const p1 = await page.evaluate(() => window.__G.player.root.position.x);
  console.log('MOVE after melee dist=', Math.hypot(p1 - p0).toFixed(2));

  // --- teste 2: cast de magia ---
  await page.evaluate(() => { window.__G.magic.castSlot(1); });
  const castStates = [];
  for (let i = 0; i < 10; i++) {
    await sleep(200);
    const s = await page.evaluate(() => window.__G.player.state);
    castStates.push(s);
  }
  console.log('CAST states:', castStates.join(','));
  const p2 = await page.evaluate(() => window.__G.player.root.position.x);
  await page.keyboard.down('KeyW'); await sleep(1000); await page.keyboard.up('KeyW');
  const p3 = await page.evaluate(() => window.__G.player.root.position.x);
  console.log('MOVE after cast dist=', Math.hypot(p3 - p2).toFixed(2));

  // --- teste 3: segundo ataque melee após cast ---
  await page.mouse.down(); await sleep(60); await page.mouse.up();
  const after = [];
  for (let i = 0; i < 6; i++) { await sleep(200); after.push(await page.evaluate(() => window.__G.player.state)); }
  console.log('MELEE-2 states:', after.join(','));

  // --- teste 4: dano recebido (estado hurt volta?) ---
  await page.evaluate(() => { window.__G.player.takeDamage(5, {}); });
  const hurt = [];
  for (let i = 0; i < 6; i++) { await sleep(250); hurt.push(await page.evaluate(() => window.__G.player.state)); }
  console.log('HURT states (sem input):', hurt.join(','));

  console.log('--- ERRORS ---');
  errors.slice(0, 10).forEach(e => console.log(e));
  if (!errors.length) console.log('(nenhum)');
  await browser.close(); process.exit(0);
})().catch(e => { console.error('FAIL', e); process.exit(1); });

