  let p = decodeURIComponent(req.url.split('?')[0]); if (p === '/') p = '/index.html';
  const file = path.join(ROOT, p);
  if (!file.startsWith(ROOT) || !fs.existsSync(file) || fs.statSync(file).isDirectory()) { res.writeHead(404); res.end(); return; }
  res.writeHead(200, { 'Content-Type': MIME[path.extname(file)] || 'application/octet-stream' });
  fs.createReadStream(file).pipe(res);
}).listen(8995);
const sleep = (ms) => new Promise(r => setTimeout(r, ms));

(async () => {
  const browser = await puppeteer.launch({ executablePath: '/usr/bin/chromium', headless: 'new', args: ['--no-sandbox', '--disable-dev-shm-usage', '--use-gl=angle', '--use-angle=swiftshader'], protocolTimeout: 180000 });
  const page = await browser.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push('[pageerror] ' + e.message));
  await page.goto('http://localhost:8995/', { waitUntil: 'domcontentloaded' });
  await sleep(5000);
  await page.evaluate(() => { window.__GAME.startGame(false); });
  await sleep(2500);
  await page.evaluate(() => { const G = window.__G; G.ui?.endDialog?.(); G.ui?.closeModalSilent?.(); G.paused = false; });
  await sleep(300);
  await page.evaluate(() => {
    const G = window.__G;
    G.element = 'fogo'; G.spells['fogo_1'] = { level: 1, uses: 0 };
    G.story.recalcStats(); G.mp = G.maxMp;
  });

  // movimento: posição completa
  const p0 = await page.evaluate(() => window.__G.player.root.position.toArray().map(v => +v.toFixed(2)));
  await page.keyboard.down('KeyW'); await sleep(1000); await page.keyboard.up('KeyW');
  const p1 = await page.evaluate(() => window.__G.player.root.position.toArray().map(v => +v.toFixed(2)));
  console.log('MOVE', JSON.stringify({ from: p0, to: p1 }));

  // cast: estado + stateT ao vivo
  await page.evaluate(() => { window.__G.magic.castSlot(1); });
  for (let i = 0; i < 6; i++) {
    await sleep(250);
    const s = await page.evaluate(() => ({ st: window.__G.player.state, t: +window.__G.player.stateT.toFixed(2), paused: window.__G.paused }));
    console.log('CAST t+' + (i * 0.25), JSON.stringify(s));
  }

  // hurt: idem
  await page.evaluate(() => { window.__G.player.takeDamage(5, {}); });
  for (let i = 0; i < 4; i++) {
    await sleep(250);
    const s = await page.evaluate(() => ({ st: window.__G.player.state, t: +window.__G.player.stateT.toFixed(2) }));
    console.log('HURT t+' + (i * 0.25), JSON.stringify(s));
  }

  console.log('--- ERRORS ---');
  errors.slice(0, 10).forEach(e => console.log(e));
  if (!errors.length) console.log('(nenhum)');
  await browser.close(); process.exit(0);
})().catch(e => { console.error('FAIL', e); process.exit(1); });

