doBowShot(heavy) {
  const dmgBase = 5 + G.attributes.forca * 1.0 + (G.equipment.weapon ? G.equipment.weapon.dmg * 1.4 : 0);
  const dmg = dmgBase * (heavy ? 1.9 : 1) * rand(0.9, 1.15);
