const puppeteer = require('puppeteer-core');
const http = require('http'); const fs = require('fs'); const path = require('path');
const ROOT = '/home/runner/work/PlayGround/PlayGround';
const MIME = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css' };
http.createServer((req, res) => {
  let p = decodeURIComponent(req.url.split('?')[0]); if (p === '/') p = '/index.html';
  const file = path.join(ROOT, p);
  if (!file.startsWith(ROOT) || !fs.existsSync(file) || fs.statSync(file).isDirectory()) { res.writeHead(404); res.end(); return; }
  res.writeHead(200, { 'Content-Type': MIME[path.extname(file)] || 'application/octet-stream' });
  fs.createReadStream(file).pipe(res);
}).listen(8996);
const sleep = (ms) => new Promise(r => setTimeout(r, ms));

(async () => {
  const browser = await puppeteer.launch({ executablePath: '/usr/bin/chromium', headless: 'new', args: ['--no-sandbox', '--disable-dev-shm-usage', '--use-gl=angle', '--use-angle=swiftshader'], protocolTimeout: 180000 });
  const page = await browser.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push('[pageerror] ' + e.message));
  await page.setViewport({ width: 1280, height: 720 });
  await page.goto('http://localhost:8996/', { waitUntil: 'domcontentloaded' });
  await sleep(5000);
  await page.evaluate(() => { window.__GAME.startGame(false); });
  await sleep(2500);

  // 1. seleção de classe aparece?
  const sel = await page.evaluate(() => !!document.querySelector('.class-card'));
  console.log('CLASS SELECT visible=', sel);
  await page.screenshot({ path: '/tmp/opencode/shot_class.jpg', type: 'jpeg', quality: 65 });

  // 2. escolhe guerreiro
  await page.click('.class-card[data-classe="guerreiro"]');
  await sleep(600);
  const c1 = await page.evaluate(() => ({
    classe: window.__G.classe, gold: window.__G.gold,
    inv: window.__G.inventory_list.map(i => i.id),
    weapon: window.__G.equipment.weapon?.id || null, offhand: window.__G.equipment.offhand?.id || null,
    paused: window.__G.paused,
  }));
  console.log('AFTER PICK', JSON.stringify(c1));

  // 3. após 2.5s o equipamento automático
  await sleep(2600);
  const c2 = await page.evaluate(() => ({
    weapon: window.__G.equipment.weapon?.id || null, offhand: window.__G.equipment.offhand?.id || null,
    armor: window.__G.equipment.armor?.id || null,
    weaponState: window.__G.player.weaponState,
    swordVisible: window.__G.player.sword.visible, shieldVisible: window.__G.player.shield.visible,
    sheathSwordVisible: window.__G.player.sheathSword.visible,
    maxHp: window.__G.maxHp, maxMp: window.__G.maxMp,
  }));
  console.log('AFTER AUTOEQUIP', JSON.stringify(c2));

  // 4. ataque com espada funciona (clique)
  await page.evaluate(() => { const G = window.__G; G.ui?.endDialog?.(); G.ui?.closeModalSilent?.(); G.paused = false; });
  await page.mouse.move(640, 400);
  await page.mouse.down(); await sleep(60); await page.mouse.up();
  await sleep(1500);
  const c3 = await page.evaluate(() => ({ st: window.__G.player.state, drawn: window.__G.player.weaponState }));
  console.log('ATTACK warrior', JSON.stringify(c3));

  // 5. spawn goblin + melee hit
  await page.evaluate(async () => {
    const G = window.__G;
    const THREE = await import('../vendor/three.module.js');
    const p = G.player.root.position;
    const e = G.enemies.spawnAt({ type: 'goblin', rank: 'E' }, p.x, p.z + 2);
    e.state = 'idle'; e.detectRange = 0; window.__tgt = e;
  });
  await page.evaluate(() => { const t = window.__tgt; t.root.position.set(window.__G.player.root.position.x, window.__G.player.root.position.y, window.__G.player.root.position.z + 1.5); });
  await sleep(200);
  const hp0 = await page.evaluate(() => window.__tgt.hp);
  await page.mouse.down(); await sleep(60); await page.mouse.up();
  await sleep(1200);
  const hp1 = await page.evaluate(() => window.__tgt.hp);
  console.log('GOBLIN HIT', hp0.toFixed(0), '->', hp1.toFixed(0));

  // 6. mago: reload e seleciona mago
  await page.reload({ waitUntil: 'domcontentloaded' });
  await sleep(5000);
  await page.evaluate(() => { window.__GAME.startGame(false); });
  await sleep(2500);
  await page.click('.class-card[data-classe="mago"]');
  await sleep(3400);
  const c4 = await page.evaluate(() => ({
    classe: window.__G.classe, weapon: window.__G.equipment.weapon?.id,
    staffVisible: window.__G.player.staff.visible, swordVisible: window.__G.player.sword.visible,
    maxMp: window.__G.maxMp,
  }));
  console.log('MAGO', JSON.stringify(c4));

  // cast funciona como mago
  await page.evaluate(() => {
    const G = window.__G; G.ui?.endDialog?.(); G.ui?.closeModalSilent?.(); G.paused = false;
    G.element = 'fogo'; G.spells['fogo_1'] = { level: 1, uses: 0 };
    G.mp = G.maxMp;
  });
  await page.evaluate(() => window.__G.magic.castSlot(1));
  await sleep(1200);
  const c5 = await page.evaluate(() => ({ st: window.__G.player.state, mp: Math.round(window.__G.mp) }));
  console.log('MAGO CAST', JSON.stringify(c5));

  // 7. arqueiro: flecha voa
  await page.reload({ waitUntil: 'domcontentloaded' });
  await sleep(5000);
  await page.evaluate(() => { window.__GAME.startGame(false); });
  await sleep(2500);
  await page.click('.class-card[data-classe="arqueiro"]');
  await sleep(3400);
  await page.evaluate(() => { const G = window.__G; G.ui?.endDialog?.(); G.ui?.closeModalSilent?.(); G.paused = false; });
  const c6 = await page.evaluate(() => ({ classe: window.__G.classe, bow: window.__G.player.bow.visible, sword: window.__G.player.sword.visible }));
  console.log('ARQUEIRO', JSON.stringify(c6));
  await page.evaluate(async () => {
    const G = window.__G;
    const p = G.player.root.position;
    const e = G.enemies.spawnAt({ type: 'goblin', rank: 'E' }, p.x, p.z + 8);
    e.state = 'idle'; e.detectRange = 0; window.__tgt = e;
  });
  await page.mouse.down(); await sleep(60); await page.mouse.up();
  await sleep(1600);
  const c7 = await page.evaluate(() => ({ tgtHp: +window.__tgt.hp.toFixed(0), arrows: window.__G.player.arrows.length }));
  console.log('ARROW HIT', JSON.stringify(c7));

  console.log('--- ERRORS ---');
  errors.slice(0, 12).forEach(e => console.log(e));
  if (!errors.length) console.log('(nenhum)');
  await browser.close(); process.exit(0);
})().catch(e => { console.error('FAIL', e); process.exit(1); });

