MAGO {"classe":"mago","weapon":"cajado_aprendiz","staffVisible":true,"swordVisible":false,"maxMp":150}
MAGO CAST {"st":"cast","mp":142}
ARQUEIRO {"classe":"arqueiro","bow":true,"sword":false}
ARROW HIT {"tgtHp":8,"arrows":0}
--- ERRORS ---
(nenhum)

