  mesh.scale.setScalar(size * 0.4);
  mesh.renderOrder = 6;
  this.scene.add(mesh);
  this.tempMeshes.push({ mesh, life: 0.22, maxLife: 0.22, radius: size, opacity: 0.85, slash: true });
