// rotina: dia → trabalho/rota; noite → casa
updateRoutine(hour) {
  const night = hour < 6.5 || hour > 19.5;
  if (night) {
    // patrulha noturna: guardas continuam a rota mesmo à noite
    if (!this.def.nightPatrol) {
      const dest = this.house;
      this.moving = dist2d(this.root.position.x, this.root.position.z, dest.x, dest.z) > 1.6;
      this.destX = dest.x; this.destZ = dest.z;
      this.routeIdx = 0;
      return;
    }
  }
  // rota de patrulha: cicla pelos pontos de interesse
  if (this.def.route) {
    const rt = this.def.route;
    if (this.routeIdx === undefined) this.routeIdx = 0;
    const wp = rt[this.routeIdx % rt.length];
    const d = dist2d(this.root.position.x, this.root.position.z, wp.x, wp.z);
    if (d < 1.2) {
      // chegou: pausa um pouco e vai ao próximo
      this.routeWait = (this.routeWait || rand(2, 5)) - (this._lastRoutineGap || 1);
      this.moving = this.routeWait > 0;
      if (!this.moving) { this.routeIdx++; this.routeWait = undefined; }
      return;
    }
    this.moving = true;
    this.destX = wp.x; this.destZ = wp.z;
    return;
