onObjectiveFlag(id, objId) {
  const q = QUEST_DEFS[id];
  if (!q || !this.activeIds.includes(id)) return;
  const o = q.objectives.find(x => x.id === objId);
  if (!o) return;
  this.progress[id][objId] = 1;
  this._tick(id, o, 1, 1);
  this._checkComplete(id);
}

_tick(id, o, cur, target) {
  if (cur === target) {
