const puppeteer = require('puppeteer-core');
const http = require('http'); const fs = require('fs'); const path = require('path');
const ROOT = '/home/runner/work/PlayGround/PlayGround';
const MIME = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css' };
http.createServer((req, res) => {
  let p = decodeURIComponent(req.url.split('?')[0]); if (p === '/') p = '/index.html';
  const file = path.join(ROOT, p);
  if (!file.startsWith(ROOT) || !fs.existsSync(file) || fs.statSync(file).isDirectory()) { res.writeHead(404); res.end(); return; }
  res.writeHead(200, { 'Content-Type': MIME[path.extname(file)] || 'application/octet-stream' });
  fs.createReadStream(file).pipe(res);
}).listen(8997);
const sleep = (ms) => new Promise(r => setTimeout(r, ms));

(async () => {
  const browser = await puppeteer.launch({ executablePath: '/usr/bin/chromium', headless: 'new', args: ['--no-sandbox', '--disable-dev-shm-usage', '--use-gl=angle', '--use-angle=swiftshader'], protocolTimeout: 180000 });
  const page = await browser.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push('[pageerror] ' + e.message + ' @ ' + (e.stack || '').split('\n')[1]));
  await page.setViewport({ width: 1280, height: 720 });
  await page.goto('http://localhost:8997/', { waitUntil: 'domcontentloaded' });
  await sleep(5000);
  await page.evaluate(() => { window.__GAME.startGame(false); });
  await sleep(2500);

  // 1. classe guerreiro + autoequip
  await page.click('.class-card[data-classe="guerreiro"]');
  await sleep(3200);
  const c1 = await page.evaluate(() => ({
    classe: window.__G.classe, weapon: window.__G.equipment.weapon?.id,
    shield: window.__G.equipment.offhand?.id, npcCount: window.__G.npcs.npcs.length,
  }));
  console.log('CLASS+EQUIP', JSON.stringify(c1));

  // 2. telport à cidade e verifica rotas de NPC
  await page.evaluate(() => { const G = window.__G; G.paused = false; G.player.root.position.set(0, window.__G.player.root.position.y, -250); });
  await sleep(4000);
  const c2 = await page.evaluate(() => {
    const out = {};
    for (const n of window.__G.npcs.npcs) {
      if (n.def.route) {
        const moved = Math.hypot(n.root.position.x - n.def.route[0].x, n.root.position.z - n.def.route[0].z);
        out[n.def.id] = { moving: n.moving, atWaypoint: moved < 8 };
      }
    }
    return out;
  });
  console.log('ROUTES', JSON.stringify(c2));

  // 3. props da cidade no scene
  const c3 = await page.evaluate(() => {
    let carts = 0, benches = 0, lamps = 0, barrels = 0;
    window.__G.scene.traverse(o => {
      if (o.type === 'Group' || o.type === 'Mesh') { /* count by geometry type */ }
    });
    const G = window.__G;
    // conta colisores novos (cart etc)
    return { torchFlames: G.world.torchFlames.length, colliders: G.world.colliders.length };
  });
  console.log('CITY', JSON.stringify(c3));
  await page.screenshot({ path: '/tmp/opencode/shot_city.jpg', type: 'jpeg', quality: 65 });

  // 4. quest chain: simula invasão completa
  await page.evaluate(() => {
    const G = window.__G;
    G.quests.complete('main_invasao');
  });
  await sleep(500);
  const c4 = await page.evaluate(() => ({ active: window.__G.quests.activeIds }));
  console.log('AFTER INVASAO', JSON.stringify(c4));
  // fala com ferreiro
  await page.evaluate(() => { window.__G.story.onTalkTo('blacksmith'); });
  await sleep(400);
  const c5 = await page.evaluate(() => ({ active: window.__G.quests.activeIds, done: window.__G.quests.doneIds }));
  console.log('AFTER TALK SMITH', JSON.stringify(c5));

  // 5. morte de 5 goblinGuerreiro conclui Estrada Perigosa
  await page.evaluate(() => {
    const G = window.__G;
    for (let i = 0; i < 5; i++) {
      const fake = { typeId: 'goblinGuerreiro', boss: false, root: { position: { x: 200, z: 100 } } };
      G.quests.onKill(fake);
    }
  });
  await sleep(400);
  const c6 = await page.evaluate(() => ({ done: window.__G.quests.doneIds, gold: window.__G.gold }));
  console.log('QUEST CHAIN DONE', JSON.stringify(c6));

  // 6. save/load com classe
  await page.evaluate(() => window.__GAME.save());
  await page.reload({ waitUntil: 'domcontentloaded' });
  await sleep(4000);
  await page.evaluate(() => { window.__GAME.startGame(true); });
  await sleep(2500);
  const c7 = await page.evaluate(() => ({ classe: window.__G.classe, weapon: window.__G.equipment.weapon?.id, weaponState: window.__G.player.weaponState }));
  console.log('SAVE/LOAD', JSON.stringify(c7));

  console.log('--- ERRORS ---');
  errors.slice(0, 10).forEach(e => console.log(e));
  if (!errors.length) console.log('(nenhum)');
  await browser.close(); process.exit(0);
})().catch(e => { console.error('FAIL', e); process.exit(1); });

