updateTestCinematic(dt) {
  const st = this.testState;
  if (!st) return;
  st.t += dt;
  const pl = G.player;
  pl.root.rotation.y = pl.yaw;
  pl.updatePose(dt);
  const crystal = G.world.crystal;
  // posição de MUNDO do cristal (ele vive dentro do keep, coords locais ≠ mundo)
